// ── Company profiles: key people + origin stories ────────────────────────────
// Rich-card enrichment for the map, keyed by AICompany.id. Merged into each
// company by bundledCompanies() in lib/companies.ts, so the same profile flows
// to BOTH the database seed and the client fallback — they can never drift.
//
// `people` groups the real, verified individuals worth reaching out to for
// networking / job-hunting: founders, C-suite, and talent/hiring contacts.
//
// Kept in its own file (rather than inline in companies-data.ts) so the
// research pass is reviewable in one place and the giant dataset file stays
// diff-friendly.
//
// Hard rule, no exceptions: ONLY real, verified data. A person we can't confirm
// currently holds the role is left out; a story we can't ground in public fact
// is left blank. A wrong name is worse than no name. Every entry is backed by
// public sources (the company's own site, Crunchbase, LinkedIn, Wikipedia,
// reputable press). Generated by the research pass; safe to hand-edit after.

import type { KeyPerson } from './types';

export interface CompanyProfile {
  /** Real, verified key people — founders, execs, and hiring/talent contacts. */
  people?: KeyPerson[];
  /** 2–3 factual sentences on how the company came to be / what it is known for. */
  story?: string;
  /** Plain-language funding / ownership status, e.g. "Series B", "Public",
   *  "Government", "Private", "Bootstrapped", "Subsidiary". */
  fundingStage?: string;
  /** A few publicly-known marquee customers or partners. */
  notableClients?: string[];
}

export const COMPANY_PROFILES: Record<string, CompanyProfile> = {
  "mila": {"people":[{"name":"Yoshua Bengio","title":"Founder & Scientific Advisor","role":"founder"},{"name":"Valérie Pisano","title":"President & Chief Executive Officer","role":"executive","linkedIn":"https://www.linkedin.com/in/valeriepisano"},{"name":"Hugo Larochelle","title":"Scientific Director","role":"executive"}],"story":"Founded in 1993 by Yoshua Bengio as a machine-learning lab (LISA) at Université de Montréal, Mila grew into one of the world's largest academic deep-learning institutes. It now federates 140+ affiliated professors across UdeM, McGill, Polytechnique and HEC Montréal, and Bengio shared the 2018 Turing Award for his pioneering deep-learning research.","fundingStage":"Non-profit"},
  "ivado": {"people":[{"name":"Aaron Courville","title":"Scientific Director","role":"executive"}],"story":"IVADO was launched in 2016 as an interdisciplinary AI research and knowledge-mobilization consortium led by Université de Montréal alongside HEC Montréal, Polytechnique Montréal and other partners, with Yoshua Bengio as its founding scientific director. In 2023 its R3AI project won a $124.5-million grant from the Canada First Research Excellence Fund.","fundingStage":"Non-profit"},
  "mcgill-cim": {"people":[{"name":"Derek Nowrouzezahrai","title":"Director, Centre for Intelligent Machines","role":"executive"}],"story":"McGill's Centre for Intelligent Machines has operated since 1985 as an inter-departmental, inter-faculty research group spanning electrical and computer engineering, mechanical engineering and computer science. It houses multiple laboratories in robotics, computer vision and intelligent systems, and has been directed over the years by researchers including Gregory Dudek.","fundingStage":"University lab"},
  "real-lab": {"people":[{"name":"Liam Paull","title":"Founder & Director","role":"founder","linkedIn":"https://ca.linkedin.com/in/liam-paull-83a5442b"}],"story":"The Robotics and Embodied AI Lab (REAL) is a Université de Montréal and Mila lab founded and led by Liam Paull, a former MIT CSAIL research scientist and CIFAR AI Chair. It works on robot perception, SLAM, uncertainty modelling and learning from simulation and demonstration; Paull also co-founded the Duckietown educational robotics platform.","fundingStage":"University lab"},
  "microsoft-research-montreal": {"people":[{"name":"Geoff Gordon","title":"Partner Researcher & Research Director, Microsoft Research Montréal","role":"executive"}],"story":"Microsoft Research Montreal was established in 2017 when Microsoft acquired Maluuba, a natural-language deep-learning startup founded in 2011 whose co-founders Sam Pasupalak and Kaheer Suleman joined Microsoft. The lab focuses on teaching machines to read, reason and communicate, with Yoshua Bengio serving as an advisor following the acquisition.","fundingStage":"Subsidiary (Microsoft)"},
  "meta-fair-montreal": {"people":[{"name":"Joëlle Pineau","title":"Founding Head, FAIR Montreal","role":"founder"}],"story":"Meta (then Facebook) opened its FAIR Montreal lab in September 2017 under founding head Joëlle Pineau, a McGill University professor, alongside researchers Pascal Vincent, Mike Rabbat and Nicolas Ballas. The lab pursues open, fundamental AI research with a focus on reinforcement learning and dialogue systems, and Meta committed funding to the local AI ecosystem.","fundingStage":"Subsidiary (Meta)"},
  "google-deepmind-montreal": {"people":[{"name":"Hugo Larochelle","title":"Founding Head, Google Brain Montreal","role":"founder"}],"story":"Google opened its Brain Montreal lab in November 2016, established and led by deep-learning researcher Hugo Larochelle, with several million dollars invested in local AI research. After Google Brain merged with DeepMind in 2023, the lab became part of Google DeepMind, with Larochelle continuing to lead its research.","fundingStage":"Subsidiary (Google DeepMind)"},
  "samsung-ai-montreal": {"people":[{"name":"Gregory Dudek","title":"Lab Director & VP, Research (Samsung AI Center Montréal)","role":"founder"}],"story":"Samsung opened its AI Center Montréal in 2018 — the fourth Samsung AI center in North America after Silicon Valley, New York and Toronto — led by McGill computer-science and robotics professor Gregory Dudek. The lab develops advanced wireless communications, robotics and multimodal machine learning.","fundingStage":"Subsidiary (Samsung)"},
  "borealis-ai": {"people":[{"name":"Foteini Agrafioti","title":"Co-founder & Head, RBC Borealis","role":"founder","linkedIn":"https://www.linkedin.com/in/agrafioti/"},{"name":"Greg Mori","title":"Research Director / VP, Research","role":"executive"}],"story":"RBC launched Borealis AI in 2016 as Canada's first bank-owned industrial AI research institute, co-founded and led by Foteini Agrafioti, who is also RBC's Chief Science Officer. Now branded RBC Borealis, it operates labs across Canada — including a Montreal lab focused on natural-language processing — researching AI applications for finance.","fundingStage":"Subsidiary (RBC)"},
  "servicenow-research": {"people":[{"name":"Nicolas Chapados","title":"Vice President, AI Research","role":"executive"}],"story":"ServiceNow Research was created from ServiceNow's 2020 acquisition of Montreal's Element AI, an AI firm founded in 2016 by Jean-François Gagné, Nicolas Chapados, Philippe Beaudoin, Anne Martel, Jean-Sébastien Cournoyer and Yoshua Bengio. The lab advances enterprise large language models and agents, with Bengio staying on as a technical advisor.","fundingStage":"Subsidiary (ServiceNow)","notableClients":["Nvidia"]},
  "huawei-noahs-ark": {"story":"Huawei's Noah's Ark Lab Montreal is the Canadian arm of Huawei's global Noah's Ark research network, expanded in Canada around 2018 and directed locally by Yanhui Geng. It researches NLP, speech, vision and data mining, partnering with McGill, the University of Waterloo, Université de Montréal and Mila.","fundingStage":"Subsidiary (Huawei)"},
  "cohere-montreal": {"people":[{"name":"Aidan Gomez","title":"Co-founder & CEO","role":"founder"},{"name":"Ivan Zhang","title":"Co-founder","role":"founder"},{"name":"Nick Frosst","title":"Co-founder","role":"founder"},{"name":"Joëlle Pineau","title":"Chief AI Officer","role":"executive"}],"story":"Cohere is an enterprise large-language-model company founded in 2019 by Aidan Gomez (a co-author of the 'Attention Is All You Need' transformer paper), Ivan Zhang and Nick Frosst, and headquartered in Toronto. It opened a Montreal office inside Mila in 2025 and hired former Meta AI head Joëlle Pineau; the company has raised hundreds of millions of dollars at a multibillion-dollar valuation.","fundingStage":"Private","notableClients":["Oracle","Fujitsu"]},
  "ericsson-gaia": {"story":"Ericsson unveiled its Global Artificial Intelligence Accelerator (GAIA) innovation hub in Montréal's Saint-Laurent district on May 2, 2019, creating more than 30 data-science and machine-learning jobs to apply AI and automation to telecom networks. The Montreal hub is part of Ericsson's global GAIA network spanning the US, Sweden and India, and partners with local universities.","fundingStage":"Subsidiary (Ericsson)"},
  "thales-cortaix": {"people":[{"name":"Siegfried Usal","title":"Managing Director, cortAIx (VP, Research & Technology Strategy)","role":"executive"}],"story":"Thales announced its cortAIx AI research centre on October 10, 2017, choosing Montreal as a global AI hub in collaboration with Mila, IVADO and Toronto's Vector Institute. Based in the O Mile-Ex complex, it opened in early 2018 with about 50 planned research jobs and builds safe, trustworthy AI for critical systems across Thales's aerospace, defence and transport businesses.","fundingStage":"Subsidiary (Thales)"},
  "coveo": {"people":[{"name":"Laurent Simoneau","title":"Co-founder (President & CTO)","role":"founder"},{"name":"Richard Tessier","title":"Co-founder","role":"founder"},{"name":"Marc Sanfaçon","title":"Co-founder","role":"founder"},{"name":"Karine Hamel","title":"Chief Financial Officer","role":"executive"},{"name":"Peter Curran","title":"Chief Product Officer","role":"executive"},{"name":"Priscila Garcia","title":"Chief Customer Officer","role":"executive"},{"name":"Chelsea Finnemore","title":"Chief Human Resources Officer","role":"hiring","linkedIn":"https://www.linkedin.com/in/chelsea-finnemore/"}],"story":"Coveo was founded in 2005 in Quebec City as a spin-off of Copernic Technologies by Laurent Simoneau, Richard Tessier and Marc Sanfaçon. Louis Têtu, former CEO of Taleo, joined as chairman and CEO in 2008 and led the company to a US$1B+ valuation. Coveo went public on the Toronto Stock Exchange (TSX: CVO) in 2021 and sells an AI-relevance platform for enterprise search, recommendations and generative AI.","fundingStage":"Public"},
  "hopper": {"people":[{"name":"Frederic Lalonde","title":"Co-founder & CEO","role":"founder"},{"name":"Joost Ouwerkerk","title":"Co-founder & CTO","role":"founder"},{"name":"Ken Pickering","title":"VP Engineering","role":"executive"},{"name":"Patrick Surry","title":"Chief Data Scientist","role":"executive"}],"story":"Hopper was founded in 2007 by former Expedia executives Frederic Lalonde and Joost Ouwerkerk, spending its early years building a large structured database of travel pricing before launching its public app in 2015. The Montreal-based company uses AI to predict flight and hotel prices and sells travel-fintech products such as price-freeze and cancellation options. It has raised more than US$700M, surpassing a US$5B valuation, with Capital One as a major investor and partner behind its HTS B2B arm.","fundingStage":"Private","notableClients":["Capital One","Nubank","Kakao"]},
  "botpress": {"people":[{"name":"Sylvain Perron","title":"Co-founder & CEO","role":"founder","linkedIn":"https://ca.linkedin.com/in/slvnperron"},{"name":"Jean-Bernard Perron","title":"Co-founder & CFO","role":"founder"},{"name":"Ameer Aftab","title":"Chief Revenue Officer","role":"executive"},{"name":"Pierre-Luc Bellerose","title":"VP Engineering","role":"executive"}],"story":"Botpress was founded in 2017 in Quebec by Sylvain Perron and co-founders as an open-source, developer-first conversational AI framework that grew a large GitHub following. Now headquartered in Montreal, it has pivoted to an LLM-powered platform for building, deploying and managing AI agents in production. The company raised a US$25M (C$34M) Series B in 2025, following an earlier Series A led by Inovia Capital.","fundingStage":"Series B"},
  "lightspeed": {"people":[{"name":"Dax Dasilva","title":"Founder","role":"founder","linkedIn":"https://ca.linkedin.com/in/daxdasilva"},{"name":"Asha Bakshani","title":"Chief Financial Officer","role":"executive","linkedIn":"https://www.linkedin.com/in/asha-hotchandani-bakshani-1b416814/"},{"name":"Bhawna Singh","title":"Chief Technology Officer","role":"executive"},{"name":"John Shapiro","title":"Chief Product Officer","role":"executive"},{"name":"Gabriel Benavides","title":"Chief Revenue Officer","role":"executive"},{"name":"Shirvani Mudaly","title":"Chief People Officer","role":"hiring"}],"story":"Lightspeed was founded in Montreal in 2005 by Dax Dasilva, starting as point-of-sale software for retailers before expanding into a global cloud commerce platform for retail and restaurants. The company went public in 2019 and is dual-listed on the NYSE and TSX under LSPD. Dasilva stepped back and later returned as CEO, guiding the multi-billion-dollar company through several acquisitions.","fundingStage":"Public"},
  "alayacare": {"people":[{"name":"Adrian Schauer","title":"Founder & CEO","role":"founder"},{"name":"Neil Grunberg","title":"Co-founder","role":"founder"},{"name":"Andrew McDonald","title":"Chief Product and Technology Officer","role":"executive"},{"name":"Geoff Darling","title":"Chief Revenue Officer","role":"executive"},{"name":"Isaac Alexander","title":"Chief Product & Software Architect","role":"executive"},{"name":"Naomi Goldapple","title":"VP, AlayaLabs","role":"executive"}],"story":"AlayaCare was founded in 2014 by Adrian Schauer, who had previously sold workforce-management startup Vortex Connect to RedPrairie, to build modern cloud software for home and community care agencies. The Montreal-headquartered platform handles intake, scheduling, dispatch, clinical records, billing and payroll, layered with predictive AI. It raised a C$225M Series D led by investors including La Caisse (CDPQ) and Inovia.","fundingStage":"Series D"},
  "dialogue": {"people":[{"name":"Cherif Habib","title":"Co-founder & CEO","role":"founder","linkedIn":"https://ca.linkedin.com/in/cherif"},{"name":"Alexis Smirnov","title":"Co-founder & CTO","role":"founder"},{"name":"Anna Chif","title":"Co-founder & Chief Strategy Officer","role":"founder"},{"name":"Francois Lafortune","title":"Co-founder","role":"founder"},{"name":"Navaid Mansuri","title":"Chief Financial Officer","role":"executive"},{"name":"Jean-Nicolas Guillemette","title":"Chief Operating Officer","role":"executive"}],"story":"Dialogue was founded in Montreal in 2016 by Cherif Habib, Alexis Smirnov, Anna Chif and Francois Lafortune as a virtual healthcare and wellness platform using AI-assisted triage to connect members with clinicians. It went public in 2021 and was acquired by Sun Life Financial in 2023 for roughly C$277M–C$365M, operating as a subsidiary. It serves millions of members across tens of thousands of employer organizations.","fundingStage":"Subsidiary (Sun Life Financial)","notableClients":["Sun Life","Canadian Tire"]},
  "sportlogiq": {"people":[{"name":"Craig Buntin","title":"Co-founder & Executive Chair","role":"founder"},{"name":"Mehrsan Javan","title":"Co-founder & CTO","role":"founder"},{"name":"Mitchell Wasserman","title":"Chief Executive Officer","role":"executive"},{"name":"Blaine Patterson","title":"Chief Commercial Officer","role":"executive"}],"story":"Sportlogiq was founded in Montreal in 2014 by former Olympic pairs figure skater Craig Buntin and computer-vision PhD Mehrsan Javan, spinning out of the TandemLaunch incubator. It uses computer vision to extract detailed analytics from broadcast footage for teams, leagues and broadcasters, particularly in hockey. In January 2026 Sportlogiq was acquired by sports-operations platform Teamworks.","fundingStage":"Acquired"},
  "flinks": {"people":[{"name":"Yves-Gabriel Leboeuf","title":"Co-founder & CEO","role":"founder"},{"name":"Frédérick Lavoie","title":"Co-founder & COO","role":"founder"}],"story":"Flinks was founded in Montreal in 2016 by Yves-Gabriel Leboeuf and Frédérick Lavoie as a financial-data platform connecting apps to consumers' bank accounts, positioning itself as a Canadian alternative to Plaid. National Bank of Canada took a majority stake in the company through a C$103M investment. The co-founders later departed and launched a new fintech, Deck.","fundingStage":"Subsidiary (National Bank of Canada)"},
  "nesto": {"people":[{"name":"Malik Yacoubi","title":"Co-founder & CEO","role":"founder"},{"name":"Karim Benabdallah","title":"Co-founder & CTO","role":"founder"},{"name":"Chase Belair","title":"Co-founder & Principal Broker","role":"founder"},{"name":"Damien Charbonneau","title":"Co-founder & COO","role":"founder"},{"name":"Marie-Eve Bernard","title":"SVP Human Resources","role":"hiring"},{"name":"Martin Aubut","title":"Chief Marketing Officer","role":"executive"},{"name":"Gabriel Barbieri","title":"SVP Finance and Treasurer","role":"executive"}],"story":"Nesto was founded in Montreal in 2018 by Malik Yacoubi, Karim Benabdallah, Chase Belair and Damien Charbonneau as a digital mortgage platform using data and machine learning to match Canadians with competitive rates. It transitioned from broker to direct lender, and in 2024 acquired the Canadian mortgage operations of CMLS Group to become one of the country's largest digital mortgage lenders.","fundingStage":"Private"},
  "nuvei": {"people":[{"name":"Philip Fayer","title":"Founder, Chair & CEO","role":"founder"},{"name":"Samir Zabaneh","title":"Chief Operating Officer","role":"executive"},{"name":"David McLaughlin","title":"Chief Financial Officer","role":"executive"},{"name":"Eli Rosner","title":"Chief Product and Technology Officer","role":"executive"}],"story":"Nuvei traces its roots to Pivotal Payments, founded in Montreal in 2003 by Philip Fayer to serve underserved small and mid-sized merchants. Rebranded Nuvei, the global payments-technology company went public on the TSX and Nasdaq (NVEI) and offers ML-based fraud prevention. In 2024 it was taken private by Advent International in an all-cash deal valuing it at roughly US$6.3B, with continued investment from Fayer, Novacap and CDPQ.","fundingStage":"Private"},
  "busbud": {"people":[{"name":"Louis-Philippe Maurice","title":"Co-founder & CEO","role":"founder"},{"name":"Michael Gradek","title":"Co-founder & CTO","role":"founder"},{"name":"Frédéric Thouin","title":"Co-founder & CAO","role":"founder"},{"name":"Marin Vallee","title":"VP Global Distribution","role":"executive"},{"name":"Emily Woolnough","title":"Talent Acquisition Manager","role":"hiring"}],"story":"Busbud was founded in Montreal in 2011 by Louis-Philippe (LP) Maurice, Michael Gradek and Frédéric Thouin after Maurice struggled to book intercity buses while traveling in South America. The marketplace lets travelers search, compare and book bus tickets worldwide, growing into one of the largest global intercity bus booking platforms across the Americas and Europe. It has raised funding for Latin American expansion, including partnering with Chilean leader Recorrido.","fundingStage":"Private"},
  "mistplay": {"people":[{"name":"Henri-Charles Machalani","title":"Co-founder & CEO","role":"founder"},{"name":"Charles Machalani","title":"Co-founder & CFO","role":"founder","linkedIn":"https://ca.linkedin.com/in/cmachalani"},{"name":"Eugene Joannides","title":"Co-founder & COO","role":"founder"},{"name":"Jason Heller","title":"Chief Executive Officer","role":"executive"},{"name":"Giordano Contestabile","title":"Chief Product Officer","role":"executive"},{"name":"Luca Fiaschi","title":"Chief Data and AI Officer","role":"executive"}],"story":"Mistplay was founded in Montreal in 2015 by Henri-Charles Machalani (a former Microsoft product manager) with co-founders including Charles Machalani and Eugene Joannides. Its mobile gaming loyalty platform rewards players for discovering and playing games, growing to millions of monthly active users. In 2021 GrowthCurve Capital made a majority investment to accelerate the company's growth, and it later expanded via the acquisition of Mobivity's loyalty platform.","fundingStage":"Private"},
  "local-logic": {"people":[{"name":"Vincent-Charles Hodder","title":"Co-founder & CEO","role":"founder"},{"name":"Gabriel Damant-Sirois","title":"Co-founder","role":"founder"},{"name":"Colin Stewart","title":"Co-founder","role":"founder"}],"story":"Local Logic was founded in 2015 by Vincent-Charles Hodder, Gabriel Damant-Sirois and Colin Stewart, who met at McGill University's School of Urban Planning. The location-intelligence platform quantifies the lifestyle and characteristics of any place using geospatial data, serving real-estate consumers, investors, developers and governments. It raised C$17.5M and reports around 100 enterprise customers reaching more than 15M users monthly.","fundingStage":"Private"},
  "keatext": {"people":[{"name":"Narjès Boufaden","title":"Founder & CEO","role":"founder"},{"name":"Charles-Olivier Simard","title":"Chief Technology Officer","role":"executive"}],"story":"Keatext was founded in Montreal in 2010 by Narjès Boufaden, a computational-linguistics PhD who specialized in natural language processing. The AI text-analytics platform synthesizes large volumes of unstructured customer feedback into recommended actions using deep learning. Its customer base has included brands and organizations such as the Quebec government, NASA, Bombardier, L'Oréal and American Express.","fundingStage":"Private","notableClients":["Bombardier","L'Oréal","American Express"]},
  "deeplite": {"people":[{"name":"Nick Romano","title":"Co-founder & CEO","role":"founder"},{"name":"Davis Sawyer","title":"Co-founder","role":"founder"},{"name":"Ehsan Saboori","title":"Co-founder & CTO","role":"founder"}],"story":"Deeplite was launched in 2017 by Ehsan Saboori and Davis Sawyer at the Montreal deep-tech incubator TandemLaunch, becoming an independent company in 2019 with Nick Romano as CEO. Its software automatically compresses and optimizes deep neural networks to run faster and smaller on edge hardware. In April 2025 Deeplite was acquired by STMicroelectronics to bolster its edge-AI offering.","fundingStage":"Acquired"},
  "brainbox-ai": {"people":[{"name":"Jean-Simon Venne","title":"Co-founder & CTO","role":"founder"},{"name":"Sean Neely","title":"Co-founder","role":"founder"},{"name":"Omar Tabba","title":"Vice-President, Products","role":"executive"},{"name":"Frank Sullivan","title":"Vice-President, Commercialization","role":"executive"},{"name":"Dominic Hand","title":"Vice President of Operations (Interim)","role":"executive"}],"story":"Founded in 2017, BrainBox AI builds autonomous AI that optimizes commercial-building HVAC systems to cut energy use and emissions, and its ARIA assistant was named to TIME's Best Inventions of 2024. The company raised successive rounds including a US$20M 2023 investment from the Quebec government and ABB. BrainBox AI was acquired by Trane Technologies in December 2024, after which CEO Sam Ramadori departed to join Yoshua Bengio's LawZero.","fundingStage":"Acquired"},
  "fluent-ai": {"people":[{"name":"Vikrant Tomar","title":"Founder & CTO","role":"founder"},{"name":"Matt Desruisseaux","title":"Co-founder","role":"founder"},{"name":"Probal Lala","title":"Chief Executive Officer","role":"executive"},{"name":"Charles Gauvin","title":"VP Product and Engineering","role":"executive"},{"name":"Edouard Chehade","title":"VP Product and Engineering","role":"executive"},{"name":"Maxime Girard","title":"VP Finance","role":"executive"}],"story":"Fluent.ai was founded in 2015 by Vikrant Tomar, who holds a McGill PhD in automatic speech recognition, and Matt Desruisseaux, spinning out of the Montreal incubator TandemLaunch. Its embedded speech-to-intent engine turns voice commands into actions entirely on-device, without the cloud, for consumer-electronics OEMs. The company raised early venture funding from investors including BDC, 500 Startups and Maple Leaf Angels.","fundingStage":"Private"},
  "korbit": {"people":[{"name":"Iulian Vlad Serban","title":"Co-founder & CEO","role":"founder"},{"name":"Ansona Onyi Ching","title":"Co-founder","role":"founder"},{"name":"Ekaterina Kochmar","title":"Co-founder","role":"founder"}],"story":"Korbit was founded in 2017 by Mila PhD researcher Iulian Vlad Serban (who worked with Yoshua Bengio, Aaron Courville and Joelle Pineau) alongside Ansona Onyi Ching and Ekaterina Kochmar, aiming to democratize education with AI-powered tutors. The Mila spin-off released a free online deep-learning course taught by an interactive AI tutor and counts Bengio, Pineau, Courville and Laurent Charlin as advisors. It raised roughly $2.65M for its personalized STEM tutoring platform.","fundingStage":"Private"},
  "waverly": {"people":[{"name":"Philippe Beaudoin","title":"Co-founder & CEO","role":"founder"},{"name":"Philippe Gagnon","title":"Co-founder & CTO","role":"founder"}],"story":"Waverly was founded in 2020 by Element AI co-founder and former Google engineer Philippe Beaudoin, alongside CTO Philippe Gagnon and other partners, to build an AI content-discovery app driven by a user's stated interests rather than engagement bait. Its app curates content based on a user-written 'manifesto' of likes and dislikes using natural-language-understanding technology. Waverly raised $1.25M CAD in pre-seed funding from FounderFuel, Panache Ventures, Hike Ventures and others; Beaudoin later joined Bengio's LawZero in 2025.","fundingStage":"Pre-seed"},
  "c2ro": {"people":[{"name":"Soodeh Farokhi","title":"Co-founder & former CTO","role":"founder"},{"name":"Riccardo Badalone","title":"Chief Executive Officer","role":"executive","linkedIn":"https://ca.linkedin.com/in/riccardo-badalone"},{"name":"Peter Goulet","title":"Chief Financial Officer","role":"executive"},{"name":"Franco Forlini","title":"Chief Operations Officer","role":"executive"},{"name":"Amir Haji","title":"VP of A.I. R&D","role":"executive"},{"name":"Mostafa Erfani","title":"VP of Engineering","role":"executive"}],"story":"C2RO was founded in 2016 by Soodeh Farokhi and incubated at Montreal's TandemLaunch, later bringing on Riccardo Badalone as CEO in 2017 while Farokhi moved to CTO. The company builds privacy-aware AI video analytics that turn existing retail cameras into computer-vision tools for labor optimization and theft deterrence. C2RO raised over US$1.1M in seed financing in 2018 and later closed a CAD$2.25M round led by Fonds InnovExport.","fundingStage":"Series A"},
  "apex": {"people":[{"name":"Manuel Del Verme","title":"Co-founder","role":"founder"},{"name":"Simone Totaro","title":"Co-founder","role":"founder"}],"story":"Apex was co-founded by Mila researchers Manuel Del Verme and Simone Totaro and was awarded Mila Startup status in July 2022. The company develops large-scale AI-based supply-and-demand market simulators intended to help decision-makers model economic and financial interactions through open market dynamics.","fundingStage":"Private"},
  "aifred-health": {"people":[{"name":"David Benrimoh","title":"Co-founder & CEO","role":"founder"},{"name":"Robert Fratila","title":"Co-founder & CTO","role":"founder"},{"name":"Sonia Israel","title":"Co-founder","role":"founder"},{"name":"Louisa Petropoulos","title":"Chief Executive Officer","role":"executive"}],"story":"Aifred Health was founded in 2016 in Montreal by David Benrimoh, Robert Fratila and Sonia Israel to build AI-driven clinical decision support for personalized mental-health treatment. Its platform combines guideline-based workflows, symptom tracking and a deep-learning model that generates remission probabilities for depression treatments. In 2024 the company received a Health Canada medical-device licence for its AI decision-support software for moderate-to-severe major depression.","fundingStage":"Seed"},
  "optable": {"people":[{"name":"Yves Poiré","title":"Co-founder","role":"founder"},{"name":"Vlad Stesin","title":"Co-founder","role":"founder"},{"name":"Bosko Milekic","title":"Co-founder","role":"founder"},{"name":"Patrick Viau","title":"Chief Revenue Officer","role":"executive"},{"name":"Crystal Jacques","title":"Vice President of Sales","role":"executive"}],"story":"Optable was founded in 2020 by Yves Poiré, Vlad Stesin and Bosko Milekic, the trio who had previously built and sold Montreal adtech firm AdGear to Samsung Ads in 2016. The company builds data clean-room technology that lets advertisers and publishers match audiences while protecting user privacy. Optable raised a US$20M (CAD$26M) Series A in 2023 led by Brightspark Ventures, followed by a Series A extension in 2025 led by Telus Global Ventures.","fundingStage":"Series A"},
  "phyla": {"people":[{"name":"Luca Cuccia","title":"Co-founder & CEO","role":"founder"},{"name":"Michael Golfi","title":"Co-founder","role":"founder"},{"name":"Ryszard Kubinski","title":"Co-founder & CSO","role":"founder"},{"name":"Paul Godin","title":"Co-founder & COO","role":"founder","linkedIn":"https://ca.linkedin.com/in/paul-godin-99124414"}],"story":"Founded in Montreal as Phyla and later rebranded to Injoy (Intestinal Joy), the company was co-founded by Luca Cuccia, Michael Golfi, Ryszard Kubinski and Paul Godin to reimagine gut health. It combines AI, at-home microbiome stool testing and a Bluetooth bathroom sensor with a companion app to turn gut data into personalized recommendations. The startup was incubated at Centech and Creative Destruction Lab.","fundingStage":"Private"},
  "valence-labs": {"people":[{"name":"Daniel Cohen","title":"Co-founder","role":"founder"},{"name":"Prudencio Tossou","title":"Co-founder","role":"founder"},{"name":"Sébastien Giguère","title":"Co-founder","role":"founder"},{"name":"Therence Bois","title":"Co-founder","role":"founder"}],"story":"Valence Labs originated as Valence Discovery, a Mila-rooted AI drug-discovery startup co-founded by Daniel Cohen, Prudencio Tossou, Sébastien Giguère and Therence Bois with mentorship from Yoshua Bengio. It pioneered low-data machine learning for designing small molecules from sparse datasets. In May 2023 it was acquired by Recursion (NASDAQ: RXRX) and now operates as a semi-autonomous AI research engine, led by co-founder Daniel Cohen with continued advisory from Bengio.","fundingStage":"Acquired"},
  "dreamfold": {"people":[{"name":"Maksym Korablyov","title":"Co-founder & CEO","role":"founder"},{"name":"Jarrid Rector-Brooks","title":"Co-founder & Chief Scientific Officer","role":"founder"},{"name":"Alexandre Stein","title":"Chief Operating Officer","role":"executive"}],"story":"Dreamfold is a protein-design startup founded by Mila researchers Maksym Korablyov and Jarrid Rector-Brooks, drawing on work alongside Michael Bronstein and Yoshua Bengio. The company builds generative AI models for designing functional proteins, most notably its FoldFlow family of SE(3) flow-matching models for protein-backbone generation. It is backed by investors including IQ Capital and OpenOcean.","fundingStage":"Private"},
  "ventus-therapeutics": {"people":[{"name":"Hao Wu","title":"Scientific co-founder (Harvard Medical School)","role":"founder"},{"name":"Richard Flavell","title":"Scientific co-founder (Yale School of Medicine)","role":"founder"},{"name":"Judy Lieberman","title":"Scientific co-founder (Boston Children's Hospital / Harvard)","role":"founder"},{"name":"Thomas Tuschl","title":"Scientific co-founder (Rockefeller University)","role":"founder"},{"name":"Dan McKay","title":"Co-founder & Head of Computational Chemistry","role":"founder"},{"name":"Marcelo Bigal","title":"President and Chief Executive Officer","role":"executive"},{"name":"Michael Crackower","title":"Chief Scientific Officer","role":"executive"},{"name":"Christine Ha","title":"Chief Financial Officer","role":"executive"},{"name":"Daniel Koerwer","title":"Chief Operating Officer","role":"executive"},{"name":"Mona Kotecha","title":"Chief Medical Officer","role":"executive"}],"story":"Ventus Therapeutics launched in 2019/2020 out of Versant Ventures' Inception discovery-engine incubator in Montreal, built on the work of scientific co-founders including Harvard's Hao Wu and Yale's Richard Flavell. It uses structural biology and its proprietary ReSOLVE computational-chemistry platform to design small-molecule drugs against hard innate-immune targets. In 2022 Ventus struck a US$700M-plus deal with Novo Nordisk for its NLRP3 inhibitor program, and its pipeline includes clinical candidates VENT-03 and VENT-02.","fundingStage":"Private","notableClients":["Novo Nordisk","Genentech"]},
  "congruence-therapeutics": {"people":[{"name":"Clarissa Desjardins","title":"Co-founder & CEO","role":"founder"},{"name":"Michael Rock Goldsmith","title":"Co-founder","role":"founder"},{"name":"Charles Grubsztajn","title":"Chief Operating Officer","role":"executive"},{"name":"Sharath Hegde","title":"Chief Scientific Officer","role":"executive"},{"name":"Michael D. Harvey","title":"Chief Development Officer","role":"executive"},{"name":"Frank Taffy","title":"Chief Business Officer","role":"executive"},{"name":"Myriam Taillefer","title":"Vice President of Finance","role":"executive"}],"story":"Congruence Therapeutics was founded in 2021 by Clarissa Desjardins (founder of Clementia Pharmaceuticals, acquired by Ipsen) and Michael Rock Goldsmith. The Montreal computationally-driven biotech designs small-molecule 'correctors' to rescue aberrant protein function in protein-misfolding diseases. Its lead candidate, CGX-926, targets MC4R-deficient genetic obesity and is in Phase I/Ib trials; the company has raised over $130M across multiple rounds, including a $39.5M financing in 2026.","fundingStage":"Series B"},
  "moov-ai": {"people":[{"name":"Dominic Danis","title":"Co-founder & CEO","role":"founder","linkedIn":"https://www.linkedin.com/in/dominicdanis/"},{"name":"Olivier Blais","title":"Co-founder","role":"founder"},{"name":"Maxime Boissonneault","title":"Co-CEO","role":"executive"},{"name":"Christian Mérat","title":"Chief Technology Officer","role":"executive"}],"story":"Founded in 2018 in Montréal, Moov AI grew into one of Canada's leading applied-AI and data consultancies, serving more than 100 clients with a team of over 60 AI professionals. In March 2025, Publicis Groupe agreed to acquire the firm, which became an AI practice within Publicis Groupe Canada.","fundingStage":"Acquired"},
  "airudi": {"people":[{"name":"Pape Wade","title":"Co-founder & CEO","role":"founder"},{"name":"Amanda Arciero","title":"Co-founder & VP Operations","role":"founder"},{"name":"Marc Plamondon","title":"VP & General Manager, Health Division","role":"executive"},{"name":"Mahecor Dieng","title":"VP & General Manager, Africa Division","role":"executive"},{"name":"Foutse Khomh","title":"Head of Artificial Intelligence & Technology","role":"executive"}],"story":"Founded in 2019 by HR experts Pape Wade and Amanda Arciero, Airudi applies artificial intelligence to human-resources management, workforce scheduling and occupational health & safety. The company partnered with Mila to advance AI in HR and its tools are used by thousands of companies in Québec and internationally.","fundingStage":"Private"},
  "hectiq-ai": {"people":[{"name":"Martin Laprise","title":"Founder & Chief Scientist","role":"founder"},{"name":"Edward Laurence","title":"Chief Technology Officer","role":"executive"}],"story":"Hectiq.AI was created in 2018 as a joint venture by Québec digital firm Mirego together with physicist and data scientist Martin Laprise, its founder and chief scientist. It researches and builds bespoke deep-learning and machine-learning technologies for businesses, including AI image processing for Celestron's Origin smart telescope.","fundingStage":"Subsidiary (Mirego)"},
  "nuenergy-ai": {"people":[{"name":"Niraj Bhargava","title":"Co-founder & CEO","role":"founder"},{"name":"Harry Major","title":"VP, Software Development","role":"executive"},{"name":"Mai Mavinkurve","title":"VP, Program Delivery","role":"executive"},{"name":"Christian Siregar","title":"VP, AI Governance Programs","role":"executive"},{"name":"Richard Barber","title":"Head, Software Business Development","role":"executive"},{"name":"Anne Graham","title":"Leadership and HR Advisor","role":"hiring"}],"story":"NuEnergy.ai, launched in 2018 and co-founded by CEO Niraj Bhargava, builds AI-governance software and services centred on its Machine Trust Platform, which measures parameters such as privacy, ethics, transparency and bias. Its platform was approved for use across all Government of Canada departments and Crown corporations, and it piloted the tool with the RCMP. The firm is anchored in Ottawa with team members in Montréal and other Canadian cities.","fundingStage":"Private"},
  "scale-ai": {"people":[{"name":"Julien Billot","title":"Chief Executive Officer","role":"executive"}],"story":"Scale AI is Canada's AI Global Innovation Cluster, a federally-funded not-for-profit created in 2018 and based in Montréal to accelerate the adoption of artificial intelligence across supply chains and industry. Led since inception by CEO Julien Billot, it co-funds industry AI projects and organizes ALL IN, one of Canada's largest AI conferences.","fundingStage":"Non-profit","notableClients":["Government of Canada"]},
  "diagram-ventures": {"people":[{"name":"François Lafortune","title":"Co-founder & CEO","role":"founder"},{"name":"Paul Desmarais III","title":"Co-founder & Chairman","role":"founder"},{"name":"Steve Schultz","title":"General Partner","role":"executive"},{"name":"Frederic Latreille","title":"General Partner","role":"executive"},{"name":"Gaurav Kapoor","title":"General Partner","role":"executive"},{"name":"Amélie Foz-Couture","title":"General Partner","role":"executive"},{"name":"Paul Manias","title":"General Partner","role":"executive"}],"story":"Diagram Ventures is a Montréal venture builder founded in 2016 by François Lafortune and Paul Desmarais III to conceive, launch and fund technology companies in fintech, insurance, climate and health. Since 2016 it has helped create companies such as Dialogue, nesto and Novisto, and it has raised multiple funds including a $100-million fund closed in 2023.","fundingStage":"Private"},
  "cdl-montreal": {"people":[{"name":"Julien Billot","title":"Site Lead, CDL-Montreal","role":"executive"},{"name":"Karine Nahi","title":"Director","role":"executive"},{"name":"Kamal Bhandal","title":"Associate Director","role":"executive"}],"story":"Creative Destruction Lab is a non-profit seed-stage accelerator founded in 2012 by Rotman professor Ajay Agrawal at the University of Toronto; its Montréal site launched in 2017 and is hosted at HEC Montréal. The objectives-based program helps massively scalable science- and technology-based startups, and includes a dedicated AI stream in Montréal.","fundingStage":"Non-profit"},
  "next-ai-montreal": {"people":[{"name":"Dominique Anglade","title":"Executive Director, Next AI Montréal","role":"executive"},{"name":"Maud Razafindramboa","title":"Director of Operations, Next AI Montréal","role":"executive"},{"name":"Jennifer Reynolds","title":"Chief Executive Officer, Next Canada","role":"executive"},{"name":"Alexandra McGregor","title":"Chief Program Officer, Next Canada","role":"executive"}],"story":"Next AI Montréal is an AI-focused accelerator launched in 2018 as a partnership between the Toronto-based non-profit NEXT Canada and HEC Montréal, delivered through the school's Executive Education arm. It takes AI-enabled ventures from ideation through prototyping and market validation, offering non-dilutive funding, mentorship and access to partner technologies.","fundingStage":"Non-profit"},
  "centech": {"people":[{"name":"Marjorick Foisy","title":"General Manager","role":"executive","linkedIn":"https://ca.linkedin.com/in/marjorick-foisy"},{"name":"Louis-Pierre Charest","title":"Senior Director, Operations and Strategy","role":"executive"},{"name":"Julian Lucchesi","title":"Senior Director, Open Innovation and Growth","role":"executive"},{"name":"Martin Enault","title":"Senior Director, Expertise Center and Entrepreneur in Residence","role":"executive"},{"name":"Elisabeth Gosselin","title":"Director, Incubation and Startup Experience","role":"executive"}],"story":"Centech is a deep-tech startup incubator founded in 1996 by École de technologie supérieure (ÉTS) to bridge university research and commercialization. Now based in Montréal's innovation district, the non-profit supports well over a hundred hardware and science ventures each year and was ranked among the world's top 10 university business incubators by UBI Global.","fundingStage":"Non-profit"},
  "district-3": {"people":[{"name":"Aaron Johnson","title":"Interim Executive Director","role":"executive"},{"name":"Anna Ehrhardt","title":"Director of Administration and Operations","role":"executive"}],"story":"District 3 is a free, equity-free startup incubator founded in 2014 at Concordia University in downtown Montréal, serving founders in tech, health, life sciences and social impact. Over its first decade it helped launch more than 1,200 companies and now operates as an innovation hub spanning several accelerator and incubator programs.","fundingStage":"Non-profit"},
  "tandemlaunch": {"people":[{"name":"Helge Seetzen","title":"Founder & CEO","role":"founder","linkedIn":"https://ca.linkedin.com/in/helgeseetzen"},{"name":"Émilie Boutros","title":"Managing Partner","role":"executive"},{"name":"Eleonora Vella","title":"Chief of Staff","role":"executive"},{"name":"Omar Zahr","title":"Chief Technology Officer","role":"executive"},{"name":"Martin Girard","title":"Director of Engineering","role":"executive"},{"name":"Sevan Stamboulian","title":"Controller","role":"executive"},{"name":"Ali Oubair","title":"HR Specialist","role":"hiring"}],"story":"TandemLaunch is a Montréal deep-tech venture foundry and seed fund founded in 2010 by Helge Seetzen, a technologist who previously worked at Dolby and Sirius XM. It builds startups around underused intellectual property from top universities and has created 30+ ventures, including Deeplite, Fluent.ai, C2RO and Sportlogiq, together worth several hundred million dollars.","fundingStage":"Private"},
  "bombardier-aviation": {"people":[{"name":"Joseph-Armand Bombardier","title":"Founder","role":"founder"},{"name":"Éric Martel","title":"President and Chief Executive Officer","role":"executive"},{"name":"Bart Demosky","title":"Executive Vice President & Chief Financial Officer","role":"executive"},{"name":"Éric Filion","title":"Executive Vice President, Programs & Supply Chain","role":"executive"},{"name":"Jean-Christophe Gallagher","title":"Executive Vice President, Aircraft Sales and Bombardier Defense","role":"executive"}],"story":"Bombardier traces to 1942, when inventor Joseph-Armand Bombardier founded L'Auto-Neige Bombardier in Québec; the company entered aerospace by acquiring Canadair in 1986. Today the publicly-traded (TSX) Montréal firm is a pure-play business-jet manufacturer known for its Challenger and Global families, with final assembly at Dorval and Mirabel. Its Global 7500 is among the longest-range business jets in service.","fundingStage":"Public"},
  "pratt-whitney-canada": {"people":[{"name":"Maria Della Posta","title":"President","role":"executive"}],"story":"Pratt & Whitney Canada was established in 1928 as the Canadian Pratt & Whitney Aircraft Company to service P&W engines, and grew into the world leader in small and medium aircraft engines from its Longueuil, Québec base. Its PT6 turboprop, launched in the 1960s, became the most-produced engine in its class, and the company is a division of Pratt & Whitney, a business unit of RTX Corporation.","fundingStage":"Subsidiary (RTX)"},
  "airbus-canada-a220": {"people":[{"name":"Benoît Schultz","title":"Chief Executive Officer, Airbus Canada","role":"executive"}],"story":"The Airbus A220 began as Bombardier's clean-sheet CSeries, designed and assembled in Mirabel, Québec. Airbus took a majority stake in the program on 1 July 2018 and rebranded it the A220; by early 2020 Bombardier had fully exited, leaving the aircraft to Airbus Canada Limited Partnership, 75% owned by Airbus with 25% held by the Government of Québec. Mirabel remains the A220's primary final-assembly line.","fundingStage":"Subsidiary (Airbus)"},
  "bell-textron-canada": {"people":[{"name":"Michael Nault","title":"Vice President and General Manager, Bell Textron Canada","role":"executive"}],"story":"Bell established its Mirabel operation on September 29, 1986, backed by an agreement with the Quebec and Canadian governments. The plant is the final assembly and delivery site for most of Bell's commercial helicopters, including the 505, 407, 429 and 412, and developed and assembles the Bell 505 Jet Ranger X. It has delivered more than 5,000 aircraft worldwide.","fundingStage":"Subsidiary (Textron)"},
  "rolls-royce-canada": {"people":[{"name":"Denis Giangi","title":"President, Rolls-Royce Canada","role":"executive","linkedIn":"https://ca.linkedin.com/in/denis-giangi-fcpa-icd-d-17850940"}],"story":"Rolls-Royce Canada Limited was established in Montreal in 1947 to maintain Merlin engines for Trans-Canada Airlines (now Air Canada) and the RCAF. Its Lachine facilities, adjacent to Montreal-Dorval airport, have grown to some 520,000 square feet with multiple test cells, and it is one of Rolls-Royce's principal North American engine service and overhaul bases, working on engines such as the BR710 and Tay used on Bombardier and Gulfstream business jets.","fundingStage":"Subsidiary (Rolls-Royce plc)","notableClients":["Bombardier","Gulfstream","Air Canada"]},
  "safran-canada": {"people":[{"name":"Bryan Teed","title":"President, Safran Landing Systems Canada","role":"executive"}],"story":"Safran's Mirabel plant, operated by Safran Landing Systems, has specialized since 1991 in manufacturing the main fitting, the central structural column of aircraft landing gear. The site supplies landing gear components for Airbus and Boeing programmes and began doubling in size in 2014. The unit traces to Messier-Bugatti-Dowty, which was renamed Safran Landing Systems in May 2016.","fundingStage":"Subsidiary (Safran)","notableClients":["Airbus","Boeing"]},
  "cae": {"people":[{"name":"Ken Patrick","title":"Founder","role":"founder"},{"name":"Matthew Bromberg","title":"President and Chief Executive Officer","role":"executive"},{"name":"Emmanuel Levitte","title":"Chief Technology Officer","role":"executive"},{"name":"Helene V. Gagnon","title":"Chief People and Sustainability Officer","role":"executive"},{"name":"Ryan McLeod","title":"Chief Financial Officer","role":"executive"}],"story":"CAE was founded in Montreal in 1947 by ex-RCAF officer Ken Patrick as Canadian Aviation Electronics Ltd, initially repairing and overhauling ground communications equipment. It built the first Canadian commercial airline flight simulator in 1955 and grew into the global leader in flight simulation and aviation training. Now publicly traded (TSX/NYSE: CAE), it employs over 13,000 people worldwide with around 4,000 at its Montreal headquarters.","fundingStage":"Public"},
  "heroux-devtek": {"people":[{"name":"Martin Brassard","title":"President and Chief Executive Officer","role":"executive"},{"name":"Stephane Arsenault","title":"Vice President and Chief Financial Officer","role":"executive"}],"story":"Héroux-Devtek traces its roots to 1942 and is the world's third-largest landing gear manufacturer, designing and building gear and actuation systems for civil and military aircraft including the Boeing 777/777X. Its history famously includes work on the landing gear for the Apollo 11 lunar module. In February 2025 it was taken private by Platinum Equity in a deal valued at about C$1.35 billion, with its headquarters kept in Longueuil.","fundingStage":"Acquired (Platinum Equity, 2025)","notableClients":["Boeing"]},
  "sonaca-montreal": {"story":"Sonaca Montréal, based in Mirabel, is the North American subsidiary of Belgium's Sonaca Group and a world leader in large aluminium wing and empennage aerostructures for civil and business aviation. It is the largest vertically integrated manufacturer of aluminium parts and assemblies up to 60 feet long in Canada. The parent Sonaca Group originated in Belgium in 1920.","fundingStage":"Subsidiary (Sonaca Group)","notableClients":["Triumph Aerostructures"]},
  "airbus-atlantic-canada": {"story":"Based in Mirabel since 2014, the company operated as STELIA Aerospace North America / STELIA Aerospace Canada before being renamed Airbus Atlantic Canada on March 17, 2023 as part of the newly formed Airbus Atlantic aerostructures division. It designs and manufactures the front and aft fuselage sections for the Airbus A220 programme and assembles the centre fuselage for the Bombardier Global 7500 business jet.","fundingStage":"Subsidiary (Airbus Atlantic)","notableClients":["Airbus","Bombardier"]},
  "mecachrome-canada": {"story":"Mecachrome Canada, in Mirabel, is the North American base of France's Mecachrome group, a high-precision engineering firm founded in 1937 in Colombes, France. The Mirabel site specializes in the manufacture and assembly of large-dimension aerostructures and hard-metal and aluminium components. It signed a long-term agreement with MHI Canada Aerospace in 2015 to supply aerostructure components; the parent group is owned by Tikehau Capital and Bpifrance.","fundingStage":"Subsidiary (Mecachrome Group)","notableClients":["MHI Canada Aerospace","Pratt & Whitney Canada","Safran"]},
  "collins-aerospace-canada": {"people":[{"name":"Louis Brunet","title":"Managing Director, Collins Aerospace Canada","role":"executive"}],"story":"Collins Aerospace was formed in 2018 by merging UTC Aerospace Systems and Rockwell Collins, and is a business of RTX. Collins has operated in Canada since 1951; its Saint-Laurent (Montreal) site provides systems engineering supporting Bombardier's commercial and business aircraft, including the former CSeries (now A220) programme.","fundingStage":"Subsidiary (RTX)","notableClients":["Bombardier"]},
  "mecaer-aviation-group": {"people":[{"name":"Michael Tabah","title":"President and CEO, Mecaer America","role":"executive"}],"story":"Mecaer Aviation Group (MAG) is an Italy-based provider of landing gear, actuation and cabin systems for rotorcraft and fixed-wing aircraft, with roots in the former SIAI Marchetti and Breda Nardi operations divested from Agusta in 1994. MAG entered North American manufacturing through the 2000 acquisition of Performance LT in Laval, and in 2016 invested C$40.4 million to make its Laval site the group's main center for landing gear design and manufacture.","fundingStage":"Subsidiary (Mecaer Aviation Group)"},
  "ge-aerospace-bromont": {"story":"GE's Bromont plant in Quebec's Eastern Townships opened in 1982 and produces fan and compressor airfoils (blades) for engines including the CFM56, GE90 and CF6, plus components for CFM/Safran programmes. One of GE Aerospace's most automated facilities, it has grown steadily since opening and later added a global robotics, automation and instrumentation R&D centre.","fundingStage":"Subsidiary (GE Aerospace)","notableClients":["CFM International","Safran"]},
  "avior-integrated-products": {"people":[{"name":"Stephen Kearns","title":"President and CEO","role":"founder"},{"name":"Danny Netto","title":"Chief Financial Officer","role":"executive"},{"name":"Jean-Michel Biron","title":"VP Technology and Innovation","role":"executive"}],"story":"Avior Integrated Products, based in Laval, is a build-to-print integrator of lightweight aircraft structures and mechanical assemblies in metal and composites. It was founded through a management buyout led by Stephen Kearns in the early 2000s and is owned in partnership by its employees together with the Fonds de solidarité FTQ and Connecticut-based Hay Island. Its founding customers were Bell Helicopter and Bombardier.","fundingStage":"Private","notableClients":["Bombardier","Bell","Airbus","Boeing"]},
  "av-and-r": {"people":[{"name":"Jean-François Dupont","title":"Co-founder","role":"founder"},{"name":"Charles Magnan","title":"Co-founder","role":"founder"}],"story":"AV&R was founded in Montreal in 1994, when Jean-François Dupont and Charles Magnan led a group of robotics and computer-vision engineers within Walsh Automation. With backing from Averna Technologies they finalized a group buyout in 2005 and rebranded as AV&R (Automation, Vision & Robotics) in 2006. It specializes in robotic surface finishing and automated visual inspection of gas-turbine engine parts, with over 2,000 machines installed worldwide.","fundingStage":"Private"},
  "dcm-aeronautique": {"people":[{"name":"Jean-Charles Raillat","title":"President and CEO","role":"executive"},{"name":"Ivan Perrier","title":"Chief Operating Officer","role":"executive"},{"name":"Daniel Dobrjanski","title":"Chief Commercial Officer","role":"executive"}],"story":"DCM Aéronautique (Groupe DCM), founded in 1987, is a vertically integrated Canadian aerospace manufacturing and MRO company specializing in aerostructure machining, welding, surface treatments, tooling and ground support equipment, with sites around Greater Montreal including Blainville, Laval, Montreal and Saint-Bruno. It is an authorized manufacturer for Bombardier and Boeing and supplies parts and sub-assemblies across the industry.","fundingStage":"Private","notableClients":["Bombardier","Boeing","Airbus","Bell","Pratt & Whitney","Safran","CAE"]},
  "abipa-canada": {"people":[{"name":"Hélène Houde","title":"President & CEO","role":"executive"}],"story":"Abipa Canada was founded in 1982 in Quebec as a precision-machining house for complex aerospace components such as engine parts, landing gear and structures. Long a portfolio company of the Fonds de solidarité FTQ and led by CEO Jean Blondin, it merged in recent years with France's ARM Group to form Abipa International, a roughly $100M business spanning six manufacturing sites across three continents. It supplies major aerospace primes and Tier-1 suppliers.","fundingStage":"Private","notableClients":["Bombardier","Pratt & Whitney","Messier-Bugatti-Dowty","Héroux-Devtek","Figeac Aéro","Mitsubishi Canada"]},
  "alten-canada": {"people":[{"name":"Jefferson Noel","title":"Managing Director","role":"executive"}],"story":"ALTEN Canada is the Canadian arm of ALTEN, a French multinational engineering and technology consultancy founded in 1988 by engineers Simon Azoulay, Laurent Schwarz and Thierry Woog. The group operates in some 30 countries and provides on-demand design, stress and systems engineering, with Montreal one of its aerospace-focused technical-services hubs. ALTEN SA is publicly listed in Paris (Euronext).","fundingStage":"Subsidiary (ALTEN)"},
  "air-canada-maintenance": {"people":[{"name":"Murray Strom","title":"Senior Vice President, Flight Operations & Maintenance","role":"executive"},{"name":"Jon Turner","title":"Vice President, Maintenance","role":"executive"}],"story":"Air Canada's maintenance and technical operations are the in-house engineering arm of Canada's largest airline, which traces its origins to Trans-Canada Air Lines, created by the federal government in 1937. Montreal-Trudeau (Dorval) serves as a primary maintenance base for the mainline fleet. Air Canada was privatized in 1988-89 and trades publicly on the Toronto Stock Exchange.","fundingStage":"Subsidiary (Air Canada)"},
  "avianor": {"people":[{"name":"Matthieu Duhaime","title":"President","role":"executive"},{"name":"Mario Lafrance","title":"Vice President & General Manager","role":"executive"}],"story":"Avianor is an independent airframe MRO and cabin-completions company based at Montreal-Mirabel (YMX), owned by DRAKKAR Aerospace & Ground Transportation. It has specialized in aircraft maintenance, repair, overhaul and cabin integration for more than 25 years. In November 2024 it inaugurated a $70M A220 Centre of Excellence at Mirabel, first announced at the 2023 Paris Air Show, and it also performs military aircraft work.","fundingStage":"Subsidiary (DRAKKAR)"},
  "ajw-technique": {"people":[{"name":"Louis Philippe Mallette","title":"Chief Executive Officer, AJW Technique","role":"executive"}],"story":"AJW Technique is a roughly 220,000-square-foot component MRO facility in Montreal and the component-repair arm of UK-based AJW Group, a nearly nine-decade-old aviation aftermarket and supply-chain company. The plant was originally opened by Canadian MRO Aveos in 2011; after Aveos collapsed into creditor protection in 2012, AJW acquired the facility, marking the group's first move into in-house repair capabilities. It repairs and overhauls aircraft components for airlines worldwide.","fundingStage":"Subsidiary (AJW Group)"},
  "nolinor-aviation": {"people":[{"name":"Marco Prud'Homme","title":"President","role":"executive"}],"story":"Nolinor Aviation is a charter and cargo airline founded in 1992 and headquartered at Montreal-Mirabel (YMX), with operations beginning in 1997. Since 2004 it has been controlled by the aviation-rooted Prud'homme family trust, and it is the world's largest operator of the Boeing 737-200, prized for gravel-runway operations to remote northern communities. Nolinor is a launch customer for Heart Aerospace's all-electric ES-30 aircraft.","fundingStage":"Private"},
  "cmc-electronics": {"people":[{"name":"Guglielmo Marconi","title":"Founder (Marconi Wireless Telegraph Company of Canada)","role":"founder"},{"name":"Pierre Rossignol","title":"President","role":"executive"}],"story":"CMC Electronics descends from the Marconi Wireless Telegraph Company of Canada, incorporated in 1903 by radio pioneer Guglielmo Marconi and later renamed the Canadian Marconi Company. Now an avionics maker of cockpit displays, GPS/GNSS receivers and flight-management systems, it was acquired by Esterline Technologies from Onex in 2007 for about US$335M; Esterline in turn was bought by TransDigm Group in 2019. It employs over 1,100 people across Montreal, Ottawa and Chicago.","fundingStage":"Subsidiary (TransDigm Group)"},
  "l3harris-mas": {"people":[{"name":"Richard Foster","title":"Chief Executive & Corporate Vice President, L3Harris Technologies Canada","role":"executive"}],"story":"L3Harris MAS at Mirabel is the Canadian in-service support and modernization division of US defence giant L3Harris Technologies, with roots in military aircraft services that moved to Mirabel in the late 1980s under the CF-188 (CF-18) fleet-management contract. Operating as Canada's Fighter Aircraft Centre of Excellence, it has provided fighter in-service support for more than 40 years and employs over 1,150 people. Its CF-18 work has drawn business from Australia, Switzerland, Finland, Spain and the US Navy.","fundingStage":"Subsidiary (L3Harris Technologies)","notableClients":["Royal Canadian Air Force","US Navy"]},
  "thales-canada-avionics": {"people":[{"name":"Chris Pogue","title":"Chief Executive Officer, Thales Canada","role":"executive"}],"story":"Thales Canada's avionics division in Saint-Laurent is part of the French Thales Group and serves as the group's centre of competence for fly-by-wire flight control systems, also designing avionics suites, head-up/head-worn displays and SATCOM for business and regional aircraft. Thales Canada employs more than 1,500 people across the country, and in 2017 the group established its Montreal-based AI research centre, cortAIx, working alongside Mila and IVADO.","fundingStage":"Subsidiary (Thales Group)"},
  "lockheed-martin-canada": {"people":[{"name":"Kristen Leroux","title":"Vice President & Regional Executive, Canada and Latin America","role":"executive"},{"name":"Stephen Isaacs","title":"General Manager, Rotary & Mission Systems Canada","role":"executive"}],"story":"Lockheed Martin Canada is the Canadian subsidiary of US aerospace and defence company Lockheed Martin, and says it has been a Canadian defence partner for nearly 80 years. It has served for more than three decades as prime contractor and combat-system integrator for the Royal Canadian Navy's Halifax-class frigates, and its SPY-7 radar and Canadian-developed CMS 330 combat management system form the backbone of the new Canadian Surface Combatant program. It also supports several RCAF platforms.","fundingStage":"Subsidiary (Lockheed Martin)","notableClients":["Royal Canadian Navy","Royal Canadian Air Force"]},
  "rheinmetall-canada": {"people":[{"name":"Pietro Mazzei","title":"President & Chief Executive Officer","role":"executive"}],"story":"Rheinmetall Canada was formed in April 1986 as Oerlikon Aerospace, the Canadian home of Oerlikon's North American business, headquartered in Saint-Jean-sur-Richelieu. Its founding mandate was the Air Defence Anti-Tank System (ADATS) for the Canadian Forces' low-level air-defence program, and that air-defence heritage still defines the company. Germany's Rheinmetall Group acquired the operation in 1999; it now builds air-defence, vehicle, soldier and counter-UAS systems.","fundingStage":"Subsidiary (Rheinmetall)"},
  "mda-space-montreal": {"people":[{"name":"Luigi Pozzebon","title":"Vice President, Satellite Systems","role":"executive"}],"story":"The MDA Space facility in Sainte-Anne-de-Bellevue is the company's centre of excellence for communications satellites, handling design, build and test under one roof. It is the direct heir to Spar Aerospace, the Canadian company that built the iconic Canadarm; Spar's space robotics division was acquired by MacDonald, Dettwiler and Associates (MDA) in 1999. MDA Space is publicly traded on the Toronto Stock Exchange and is scaling satellite capacity through its MDA AURORA product line.","fundingStage":"Subsidiary (MDA Space)"},
  "ghgsat": {"people":[{"name":"Stéphane Germain","title":"Founder & CEO","role":"founder"},{"name":"Emilie Hamel","title":"Chief Operating Officer","role":"executive"},{"name":"Jeffrey Kadanoff","title":"Chief Financial Officer","role":"executive"},{"name":"Sonia Kim","title":"Chief Product Officer","role":"executive"},{"name":"Linda Barabé","title":"VP, People & Culture","role":"hiring"}],"story":"GHGSat was founded in December 2011 by Stéphane Germain in Montreal to measure greenhouse-gas emissions from individual industrial facilities from space. In 2016 it launched its demonstrator satellite, Claire, becoming the first to attribute methane emissions to specific facilities, and it has since built a constellation detecting leaks as small as 100 kg/hr. Backed by investors including Fonds de solidarité FTQ and BDC Capital, it raised roughly $47M CAD in 2025 and monitors emissions for clients such as ExxonMobil.","fundingStage":"Private (Venture-backed)","notableClients":["ExxonMobil"]},
  "northstar-earth-space": {"people":[{"name":"Stewart Bain","title":"Co-founder & CEO","role":"founder"},{"name":"Beth Michelson","title":"President, NorthStar US","role":"executive"}],"story":"NorthStar Earth & Space was founded around 2015-2016 in Montreal by CEO Stewart Bain to deliver commercial space-situational-awareness services, aiming to be the first operator to monitor objects in orbit from space itself. Backed by investors including Telesystem and Cartesian Capital plus Canadian and Quebec government funds, it has raised well over $130M across several rounds. In 2026 it announced plans to go public on the NYSE (ticker NSTR) via a SPAC merger with Viking Acquisition Corp.","fundingStage":"Series D"},
  "ngc-aerospace": {"people":[{"name":"Jean de Lafontaine","title":"Founder & President","role":"founder"},{"name":"Jean-François Hamel","title":"Vice President, Space Systems","role":"executive"},{"name":"David Neveu","title":"Vice President, Aerial Systems","role":"executive"},{"name":"Carl Fontaine","title":"Director, Finance and Administration","role":"executive"}],"story":"NGC Aerospace was founded in 2001 in Sherbrooke by Jean de Lafontaine, an aerospace engineer and Université de Sherbrooke professor who had previously worked with the Canadian, European and Japanese space agencies. The company specializes in guidance, navigation and control software, which has flown on European Space Agency missions including the PROBA series of satellites. It grew from a single employee working out of the founder's home to a recognized Quebec GNC specialist with decades of accumulated in-orbit operations.","fundingStage":"Private","notableClients":["European Space Agency","Canadian Space Agency"]},
  "mpb-communications": {"people":[{"name":"Morrel P. Bachynski","title":"Founder","role":"founder"},{"name":"Jane Bachynski","title":"President","role":"executive"}],"story":"MPB Communications (originally MPB Technologies) was founded by Dr. Morrel P. Bachynski, beginning operations in early 1977 as a spin-off of a group of scientists and engineers from RCA Canada's Research & Development Laboratories. The privately held, self-financed firm builds photonics products including Raman fibre lasers, optical amplifiers, sensors and space subsystems. It expanded significantly in the 1990s into the undersea telecommunications market and contributes to Canadian space and photonics programmes.","fundingStage":"Private"},
  "reaction-dynamics": {"people":[{"name":"Bachar Elzein","title":"Founder, CEO & CTO","role":"founder"},{"name":"Maxime Goulet-Bourdon","title":"Chief Operating Officer","role":"executive"},{"name":"Susan McIntosh","title":"Chief Financial Officer","role":"executive"}],"story":"Reaction Dynamics was founded in 2017 (near Montreal, now headquartered in Longueuil) by aerospace engineer Bachar Elzein, whose propulsion and combustion research at École Polytechnique de Montréal underpins the company's technology. It is developing a hybrid rocket engine and a light launch vehicle called Aurora to deliver small payloads to low Earth orbit. In 2025 the company raised a CAD $14M Series A, bringing total funding to CAD $38M, and is preparing a suborbital demonstration flight.","fundingStage":"Series A"},
  "nrc-amtc": {"people":[{"name":"Mouhab Meshreki","title":"Director General, Aerospace Research Centre (NRC)","role":"executive"}],"story":"The Aerospace Manufacturing Technologies Centre is a facility of Canada's National Research Council, built in 2004 and located primarily on the campus of the Université de Montréal, with satellite facilities in Mirabel and Ottawa. It helps industry, especially the aerospace sector, develop and implement next-generation manufacturing methods such as additive manufacturing, repair technologies and robotized high-force machining. It operates as part of the NRC's Aerospace Research Centre, Canada's premier aerospace R&D organization.","fundingStage":"Government"},
  "criaq": {"people":[{"name":"Guillaume Côté","title":"President and CEO","role":"executive"}],"story":"CRIAQ (Consortium de recherche et d'innovation en aérospatiale au Québec) is a non-profit organization established in 2002 with financial support from the Québec government; André Bazergui, a former Director General of Polytechnique Montréal, served as its first President and CEO. It pioneered an industry-led collaborative research model connecting aerospace companies with universities and college technology-transfer centres. The consortium has catalysed over 150 collaborative projects involving more than 1,000 researchers and 100-plus member organizations.","fundingStage":"Non-profit"},
  "polytechnique-aerospace": {"story":"Polytechnique Montréal is an engineering school founded in 1873 and affiliated with the Université de Montréal, located on Mount Royal in the Côte-des-Neiges area. Its faculty conduct extensive aerospace research in propulsion, structures, composites, combustion and simulation, and it is a core academic partner of Quebec's aerospace cluster and the CRIAQ consortium. Its labs have trained founders and researchers active in the local space and aerospace industry.","fundingStage":"University lab"},
  "mcgill-miae": {"people":[{"name":"Siva Nadarajah","title":"Director, McGill Institute for Aerospace Engineering","role":"executive"},{"name":"Jovan Nedic","title":"Associate Director (Research)","role":"executive"},{"name":"Mathias Legrand","title":"Associate Director (Academic)","role":"executive"}],"story":"The McGill Institute for Aerospace Engineering (MIAE) is a cross-faculty institute at McGill University established in 2009 to advance aerospace research and training. It brings together more than 40 faculty members and roughly 200 graduate students across six departments and three faculties, working on aeronautics and astronautics topics spanning environment, energy, design and manufacturing. Its researchers have secured tens of millions of dollars in research and infrastructure funding.","fundingStage":"University lab"},
  "concordia-ciadi": {"people":[{"name":"Carole El Ayoubi","title":"Director, CIADI Education","role":"executive"},{"name":"Marius Paraschivoiu","title":"Director, CIADI Research","role":"executive"}],"story":"The Concordia Institute of Aerospace Design and Innovation (CIADI) is a project-based institute within Concordia University's Gina Cody School of Engineering and Computer Science, established in 2002. It pairs students with industry partners on hands-on, capstone-style aerospace design projects. The institute is closely tied to Montreal's aerospace OEMs and suppliers.","fundingStage":"University lab"},
  "ena-aerotechnique": {"story":"The École nationale d'aérotechnique (ÉNA) was created in 1964 as the Institut d'aérotechnique du Québec in Dorval and was integrated into Cégep Édouard-Montpetit in 1968, moving to purpose-built facilities near Saint-Hubert airport in 1972. It is the largest aerotechnical training institution in North America, operating six hangars with a fleet of dozens of aircraft plus specialized labs and workshops. It sits in the Saint-Hubert airport zone alongside many aerospace enterprises.","fundingStage":"Government"},
  "cta-saint-hubert": {"people":[{"name":"Frédéric Parent-Huybrechts","title":"Directeur général (General Director)","role":"executive"}],"story":"The Centre technologique en aérospatiale (CTA) is a college centre for technology transfer (CCTT) attached to the École nationale d'aérotechnique of Cégep Édouard-Montpetit, operating since 1993. Located in the Saint-Hubert airport zone, it provides applied research and technical support to help aerospace companies, from SMEs to prime contractors, solve manufacturing and innovation problems. With a team of more than 60 experts and roughly a CAD $4.5M annual budget, it carries out over 200 projects each year.","fundingStage":"Non-profit"},
  "aero-montreal": {"people":[{"name":"Mélanie Lussier","title":"Présidente-directrice générale (President and CEO)","role":"executive"}],"story":"Aéro Montréal is a strategic think-tank founded in August 2006 that unites Quebec's aerospace decision-makers, including companies, educational and research institutions, associations and unions; Suzanne M. Benoît served as its founding President until her retirement. It works to mobilize the industry around common goals and improve the cluster's competitiveness. It runs sector initiatives such as the MACH supply-chain program and now governs the Espace Aéro innovation zone.","fundingStage":"Non-profit"},
  "camaq": {"people":[{"name":"Mario Sabourin","title":"Directeur général (Director General)","role":"executive","linkedIn":"https://ca.linkedin.com/in/mario-sabourin-recrutement"}],"story":"CAMAQ (Comité sectoriel de main-d'oeuvre en aérospatiale au Québec) is a tripartite sector workforce committee that has operated for more than 40 years, working with aerospace employers and national unions to forecast and develop talent. It is best known for publishing the reference annual forecast of aerospace and air-transport employment in Québec. Its mission is to promote workforce excellence and professional development across the province's aerospace industry.","fundingStage":"Non-profit"},
  "espace-aero-mirabel": {"story":"Espace Aéro is Québec's aerospace innovation zone, announced by the Québec government in May 2024 as the province's fourth designated innovation zone, spanning Longueuil, Mirabel and Montréal under the governance of the Aéro Montréal cluster. Initial investments total around CAD $415M, including CAD $95M from the Québec government, aimed at making Québec a leader in aerospace decarbonization and advanced air mobility. Its Mirabel hub at YMX provides testing, experimentation and simulation facilities for autonomous technology, drones and aircraft manufacturing.","fundingStage":"Government"},
  "flying-whales-quebec": {"people":[{"name":"Vincent Guibout","title":"President, FLYING WHALES Québec (CEO, FLYING WHALES)","role":"executive"},{"name":"Arnaud Thioulouse","title":"Managing Director, FLYING WHALES Québec","role":"executive"}],"story":"FLYING WHALES Québec is the Quebec arm of the Franco-Quebec company FLYING WHALES, a French airship start-up founded in 2012 by Sébastien Bougon to develop the LCA60T, a large rigid cargo airship for moving heavy loads to remote regions with a low carbon footprint. The Québec government, through Investissement Québec, took an equity stake (roughly 25%) to anchor airship development and a future assembly plant in the province to serve the Americas. The project has received ongoing support from both French and Québec public authorities since 2017.","fundingStage":"Subsidiary (FLYING WHALES)"},
  "jaunt-air-mobility-canada": {"people":[{"name":"Kaydon Stanzione","title":"Co-founder & founding CEO","role":"founder"},{"name":"Martin Peryea","title":"Co-founder, CEO & CTO","role":"founder"},{"name":"Eric Côté","title":"President, Jaunt Air Mobility Canada","role":"executive"},{"name":"Yves Comeau","title":"Vice President, Finance, Jaunt Air Mobility Canada","role":"executive"}],"story":"Jaunt Air Mobility was founded by engineers Kaydon Stanzione and Martin Peryea, and in 2019 acquired Carter Aviation's Slowed-Rotor Compound (SRC) intellectual property for its 'Journey' eVTOL aircraft. It was named one of the eVTOL partners in Uber Elevate's air-taxi network, and in 2022 became a wholly owned subsidiary of AIRO Group Holdings. Its design and manufacturing operations are based in the Montreal region.","fundingStage":"Subsidiary (AIRO Group Holdings)"},
  "marinvent": {"people":[{"name":"John Maris","title":"Founder, President & CEO","role":"founder"},{"name":"Julia Maris","title":"Co-founder","role":"founder"}],"story":"Marinvent Corporation was founded in the 1980s by John Maris, a former air-force pilot and Canadian Space Agency test pilot, together with his wife Julia. The company became known for aerospace flight-test instrumentation and certification work — including the SmartProbe air-data system — serving customers from NASA to major avionics manufacturers. Maris was inducted into Canada's Aviation Hall of Fame and awarded the Trans-Canada (McKee) Trophy.","fundingStage":"Private","notableClients":["NASA"]},
  "ara-robotics": {"people":[{"name":"Pascal Chiva-Bernard","title":"Co-founder & CEO","role":"founder"},{"name":"Charles Brunelle","title":"Co-founder & COO","role":"founder"},{"name":"Guillaume Charland-Arcand","title":"Co-founder & CTO","role":"founder","linkedIn":"https://www.linkedin.com/in/guillaume-charland-eng-masc-1a76205a/"}],"story":"ARA Robotics (ARA Robotique) is a Montreal-based unmanned aerial systems company co-founded by engineering graduates Pascal Chiva-Bernard, Charles Brunelle and Guillaume Charland-Arcand. The startup designs and assembles autonomous drones in Canada, with an autopilot and turnkey aerial-robotics solutions used for automated inventory, inspection and monitoring across industries such as mining, construction and defence. It was incubated at Montreal's Centech accelerator.","fundingStage":"Private"},
  "hydro-quebec": {"people":[{"name":"Claudine Bouchard","title":"President and Chief Executive Officer","role":"executive"},{"name":"Maxime Aucoin","title":"Executive Vice President and Chief Financial Officer","role":"executive"},{"name":"François Brassard","title":"Acting Executive Vice President and Chief Operating and Infrastructure Officer","role":"executive"},{"name":"Dominic Roy","title":"Acting Senior Vice President – Talent and Organizational Development","role":"executive"}],"story":"Hydro-Québec is a Crown corporation created on April 14, 1944, when Premier Adélard Godbout's government passed the Act to establish the Québec Hydro-Electric Commission and expropriated Montreal Light, Heat and Power. It generates, transmits and distributes electricity across Québec, overwhelmingly from hydroelectric sources. Its IREQ research institute in Varennes drives battery, solar and grid R&D, and it inaugurated Québec's first utility-scale solar stations in 2021.","fundingStage":"Crown corporation"},
  "innergex": {"people":[{"name":"Gilles Lefrançois","title":"Founder","role":"founder"},{"name":"Jean Trudel","title":"President and Chief Executive Officer","role":"executive"},{"name":"Yves Baribeault","title":"Chief Legal Officer and Secretary","role":"executive"},{"name":"Niko Nikolaidis","title":"Vice President – Finance","role":"executive"}],"story":"Innergex Renewable Energy was founded in 1990 by Gilles Lefrançois to develop small hydro facilities in response to a Québec government call for private power bids. Headquartered in Longueuil, it grew into an independent producer operating roughly 90 wind, hydro, solar and storage facilities across Canada, the US, France and Chile, and was long listed on the TSX. In 2025 La Caisse (formerly CDPQ) completed a C$10-billion take-private acquisition, delisting the company.","fundingStage":"Acquired"},
  "kruger-energy": {"people":[{"name":"Jean Roy","title":"Senior Vice President and Chief Operating Officer, Kruger Energy and Real Estate","role":"executive"},{"name":"JJ Davis","title":"Vice President, Operations and Asset Management","role":"executive"}],"story":"Kruger Energy is the renewable-energy subsidiary of Montreal's Kruger Inc., a family-owned company founded in 1904 by Joseph Kruger as a fine-paper business. Established in 2004, Kruger Energy develops and operates hydroelectric, wind, solar, biomass and energy-storage projects, growing to 47 power sites with around 650 MW of installed capacity. It became a notable player in Québec wind power and later expanded into solar and battery storage.","fundingStage":"Subsidiary (Kruger Inc.)"},
  "boralex": {"people":[{"name":"Bernard Lemaire","title":"Founder","role":"founder"},{"name":"Patrick Decostre","title":"President and Chief Executive Officer","role":"executive"},{"name":"Philippe Bonin","title":"Executive Vice President and Chief Financial Officer","role":"executive"},{"name":"Marie-Josée Arsenault","title":"Executive Vice President and Chief People and Culture Officer","role":"executive"}],"story":"Boralex was founded in 1990 by Bernard Lemaire, the entrepreneur behind packaging and recycled-paper company Cascades, which moved into energy with Canada's first natural-gas cogeneration plant at Kingsey Falls. Listed on the TSX (BLX), the company develops, builds and operates wind, hydroelectric, solar and storage assets in Canada, France, the UK and the US. It is one of France's largest independent onshore wind producers, with an installed capacity of roughly 3 GW.","fundingStage":"Public"},
  "evlo": {"people":[{"name":"Sonia St-Arnaud","title":"President and Chief Executive Officer","role":"executive"},{"name":"Jean Lachance","title":"Chief Operating Officer","role":"executive"},{"name":"Evelyne Morin","title":"Director, Human Resources and OHS","role":"hiring"}],"story":"EVLO Energy Storage was launched in December 2020 as a subsidiary of Hydro-Québec to design, sell and operate utility-scale battery storage systems. Its lithium-iron-phosphate (LFP) technology stems from more than 40 years of battery-materials research at Hydro-Québec, which holds over 800 related patents. EVLO's systems have been tested on Hydro-Québec's grid, including peak-shaving and microgrid deployments and its solar farm in La Prairie.","fundingStage":"Subsidiary (Hydro-Québec)"},
  "dcbel": {"people":[{"name":"Marc-André Forget","title":"Founder & CEO","role":"founder"}],"story":"dcbel is a Montreal cleantech company founded in 2015 by Marc-André Forget. Its r16 Home Energy Station is a bidirectional home-and-EV energy hub that combines a solar and battery inverter with AI, letting solar panels and electric vehicles power a home. In 2023 the company closed a Series B of more than US$50 million led by Montréal's Idealist Capital, with participation from Investissement Québec and Volvo Cars.","fundingStage":"Series B"},
  "quebec-solar": {"story":"Quebec Solar is a Montreal-based solar installer operating since around 2014, providing design, installation and support for residential, commercial and agricultural clients. It specializes in solar panel systems and battery-backup installations, and is one of the more established dedicated solar installers on the island of Montreal.","fundingStage":"Private"},
  "volts-energies": {"story":"Volts Energies is a Québec renewable-energy specialist founded in 2003, owned and managed for over two decades by entrepreneur Sébastien Caron. It focuses on off-grid and hybrid systems — combining solar PV, wind, generators, biomass and micro-hydro — for homes, cottages and remote sites, and operates a large online store serving customers across Canada.","fundingStage":"Private"},
  "wsp-solar": {"people":[{"name":"Alexandre L'Heureux","title":"President and Chief Executive Officer, WSP Global","role":"executive"}],"story":"WSP Global is one of the world's largest professional-services and engineering firms, headquartered in Montreal, with corporate roots tracing back to 1885 and Québec engineering firm Genivar, which adopted the WSP name in 2012. Publicly listed on the TSX (WSP), it provides engineering and advisory services for renewable-energy projects including solar and wind, and has been cited among the Québec companies driving the province's solar PV sector.","fundingStage":"Public"},
  "energir": {"people":[{"name":"Éric Lachance","title":"President and Chief Executive Officer","role":"executive"},{"name":"Mathieu Lepage","title":"Chief Financial Officer","role":"executive"},{"name":"Stéphanie Trudeau","title":"Executive Vice President, Québec","role":"executive"},{"name":"Claudine Beaudet","title":"Vice President, Employees and Culture","role":"hiring"}],"story":"Énergir traces its origins to the Québec Natural Gas Corporation, which took over Hydro-Québec's gas network in 1957. Known for decades as Gaz Métropolitain and then Gaz Métro, it rebranded to Énergir in 2017 to reflect a shift toward diversified energy. It is Québec's largest natural gas distributor, delivering around 98% of the province's natural gas, and has diversified into wind power, renewable natural gas and Vermont's electric utility. Since 2022 it has been fully owned by CDPQ and Fonds de solidarité FTQ.","fundingStage":"Private"},
  "rematek": {"people":[{"name":"Mike Perrault","title":"President","role":"executive"}],"story":"Rematek Énergie created its renewable-energy division in 2009 and grew into one of the largest distributors of specialized solar and renewable-energy equipment in Eastern Canada, supplying installers, commercial owners and utilities. It handles product distribution, PV system design, project financing and training. In November 2024 it was appointed a Tesla Powerwall distributor for Québec through an agreement with Stardust Solar.","fundingStage":"Private","notableClients":["Stardust Solar"]},
  "concordia-czebs": {"people":[{"name":"Andreas K. Athienitis","title":"Director, Centre for Zero Energy Building Studies","role":"founder"},{"name":"Liangzhu Leon Wang","title":"Associate Director, Centre for Zero Energy Building Studies","role":"executive"}],"story":"The Centre for Zero Energy Building Studies was established at Concordia University around 2011-2012, building on the university's Centre for Building Studies (founded 1976). It was created by Concordia researchers led by Professor Andreas Athienitis and serves as the headquarters of the NSERC Smart Net-Zero Energy Buildings Strategic Research Network. Its solar simulator is one of only a handful of such research facilities in the world.","fundingStage":"University lab"},
  "energie-solaire-quebec": {"people":[{"name":"Patrick Goulet","title":"Président (Board President)","role":"executive"},{"name":"Jimmy Royer","title":"Vice-président","role":"executive"}],"story":"Énergie Solaire Québec is a non-profit organization founded in 1983 as Association Québec solaire, adopting its current name in 1996. Its mission is to promote the use of solar and other renewable energy in Quebec through public education and awareness. It is the province's oldest solar-energy organization, with individual and corporate members from the renewable-energy sector.","fundingStage":"Non-profit"},
  "csl-group": {"people":[{"name":"Jacques-Félix Sincennes","title":"Founder (La Compagnie du Richelieu, 1845 predecessor)","role":"founder"},{"name":"Louis Martel","title":"President and Chief Executive Officer","role":"executive"},{"name":"Chantal Picard","title":"Executive Vice-President and Chief Operating Officer","role":"executive"},{"name":"Jeff Barnes","title":"Chief Financial and Investments Officer","role":"executive"},{"name":"Stéphanie Aubourg","title":"Chief Human Resources and Digital Solutions Officer","role":"executive"},{"name":"John Sypnowich","title":"Chief Legal and Sustainability Officer","role":"executive"}],"story":"CSL Group traces its origins to 1845, when Jacques-Félix Sincennes founded La Compagnie du Richelieu to move farmers' goods along the Richelieu and St. Lawrence rivers. That company evolved through the Richelieu & Ontario Navigation Company and, via a 1913 merger of 11 shipping firms, became Canada Steamship Lines. Today the Montreal-headquartered, privately held CSL Group is the world's largest owner and operator of self-unloading bulk vessels.","fundingStage":"Private"},
  "fednav": {"people":[{"name":"Ladislas Pathy","title":"Co-founder","role":"founder"},{"name":"Ernest Pathy","title":"Co-founder","role":"founder"},{"name":"Paul Pathy","title":"President and Chief Executive Officer","role":"executive"}],"story":"Fednav was founded on September 7, 1944 as Federal Commerce & Navigation Co. Ltd. by the Pathy family (Ernest and Ladislas Pathy), initially in Toronto, relocating to Montreal in the early 1950s. The opening of the St. Lawrence Seaway in 1959 spurred major growth. Still family-owned and now led by third-generation Paul Pathy, Fednav is Canada's largest oceangoing dry-bulk shipowner, moving over 30 million tonnes of cargo worldwide.","fundingStage":"Private"},
  "oceanex": {"people":[{"name":"Sid Hynes","title":"Executive Chairman","role":"executive"},{"name":"Matthew Hynes","title":"Executive Vice President","role":"executive"},{"name":"Amy Collins","title":"Vice President, Human Resources and Labour Relations","role":"hiring"}],"story":"Oceanex was formed in 1990 through the merger of Atlantic Container Express of Montreal and Atlantic Searoute Ltd. of Halifax, with roots in Newfoundland shipping dating back over a century. It operated as an income trust until 2007, when it was privatized under executive chairman Captain Sid Hynes. Oceanex runs an intermodal service linking Montreal and Halifax to Newfoundland, importing a large share of the province's goods and vehicles.","fundingStage":"Private"},
  "port-of-montreal": {"people":[{"name":"Paul Bird","title":"President and Chief Executive Officer","role":"executive"},{"name":"Julien Baudry","title":"Vice-President, Communications and External Affairs","role":"executive"}],"story":"The Port of Montreal traces its administration to 1830, when a Harbour Commission was created to improve and expand Montreal's harbour. It has evolved through the National Harbours Board (1936), the Montreal Port Corporation (1983) and, since 1999, the Montreal Port Authority — an autonomous federal agency under the Canada Marine Act. It is Canada's second-largest port and is expanding with a new container terminal at Contrecoeur.","fundingStage":"Government"},
  "mgt": {"people":[{"name":"Michael Fratianni","title":"President and Chief Executive Officer","role":"executive"}],"story":"Montreal Gateway Terminals operates the Cast and Racine container terminals at the Port of Montreal. In 2007 Morgan Stanley's infrastructure group bought an 80% interest for about US$460 million (with Hapag-Lloyd retaining 20%, later also acquired by Morgan Stanley). In 2019 a consortium led by Fiera Axium Infrastructure acquired MGT from Morgan Stanley Infrastructure Partners. It handles a large share of Montreal's container traffic.","fundingStage":"Private"},
  "termont": {"people":[{"name":"Julien Dubreuil","title":"General Manager","role":"executive"}],"story":"Termont Montreal Inc. is a joint venture that operates the Maisonneuve and Viau container terminals at the Port of Montreal. It managed the Maisonneuve terminal for nearly 30 years and, after signing a long-term lease with the Montreal Port Authority in 2015, opened the newer Viau terminal in 2016, with MSC as its main marine user. Termont Terminal Inc. holds a 50% stake; U.S.-based SSA Marine has increased its interest in the terminal.","fundingStage":"Private","notableClients":["MSC"]},
  "logistec": {"people":[{"name":"Roger Paquin","title":"Founder","role":"founder"},{"name":"Sean Pierce","title":"Chief Executive Officer","role":"executive"},{"name":"Michel Brisebois","title":"Chief Human Resources Officer","role":"executive"}],"story":"Logistec was founded in 1952 by Roger Paquin as Quebec Terminals Ltd. It grew into a marine cargo-handling and environmental-services company operating in 60+ ports and 90 terminals across North America, long controlled by the Paquin family (with Madeleine Paquin as CEO). In January 2024, U.S. firms Blue Wolf Capital and Stonepeak completed a roughly C$1.2-billion acquisition, ending the family's seven-decade control while keeping the HQ in Montreal.","fundingStage":"Acquired"},
  "ocean-group-mtl": {"people":[{"name":"Gordon Bain","title":"Founder & Chairman","role":"founder"},{"name":"Jacques Tanguay","title":"President and Chief Executive Officer","role":"executive"},{"name":"Carole Goudreault","title":"Executive Vice President – Human Resources","role":"hiring"}],"story":"Groupe Océan (Ocean Group) was founded in 1972 by Gordon Bain, originating from the company Aqua-Marine. It entered the tug business in 1987 with the purchase of Quebec Tugs Limited. Headquartered in Quebec, it is a leading Canadian marine-services provider whose ship-docking tugs serve ports including Montreal, and it operates shipyards at Isle-aux-Coudres and Les Méchins.","fundingStage":"Private"},
  "urgence-marine": {"story":"Urgence Marine is a Montreal-based provider of marine environmental and port services — including mooring and unmooring, hold cleaning, de-icing, spill response, and waste removal — at the Port of Montreal, the Port of Quebec and regional facilities. Founded in the 1970s, its leadership passed to Jonathan Berthiaume in 2007, and it has since taken on a financial partnership with Snowdon Partners. It serves over 150 customers across Quebec.","fundingStage":"Private"},
  "cargom": {"people":[{"name":"Louis-Philippe Allard","title":"Director General (Directeur général)","role":"executive"}],"story":"CargoM, the Metropolitan Cluster of Logistics and Transportation of Montreal, was created in 2012 as part of Greater Montreal's economic-development strategy. It unites the region's port, carriers, terminals, educational institutions, research centres and industry associations around shared competitiveness and growth objectives. Its founding chair was Sylvie Vachon, then President and CEO of the Montreal Port Authority.","fundingStage":"Non-profit"},
  "ubisoft-montreal": {"people":[{"name":"Pierre-Jules Tremblay","title":"Managing Director, Ubisoft Montréal","role":"executive"}],"story":"Ubisoft Montreal opened on April 25, 1997 as Ubisoft's expansion into North America, aided by subsidies from the governments of Montreal, Quebec and Canada to create multimedia jobs. It broke out with Tom Clancy's Splinter Cell (2002) and Prince of Persia: The Sands of Time (2003), then created its own franchises including Assassin's Creed, Far Cry, Watch Dogs and For Honor. With over 4,000 staff, it is among the largest game-development studios in the world.","fundingStage":"Subsidiary (Ubisoft)"},
  "wb-games-montreal": {"story":"WB Games Montreal was founded on March 1, 2010 as a subsidiary of Warner Bros. Games. It developed Batman: Arkham Origins (2013) and supported Rocksteady Studios on Batman: Arkham Knight DLC, later releasing the co-op action game Gotham Knights in October 2022. The studio continues to develop titles based on DC and Warner Bros. properties.","fundingStage":"Subsidiary (Warner Bros. Games)"},
  "eidos-montreal": {"people":[{"name":"Stéphane D'Astous","title":"Founder & General Manager","role":"founder"}],"story":"Eidos-Montréal was founded on November 26, 2007 by Stéphane D'Astous as a subsidiary of Eidos Interactive, later becoming part of Square Enix in 2009. The studio is best known for rebooting Deus Ex with Human Revolution (2011) and Mankind Divided (2016) and for the Guardians of the Galaxy game. In 2022 Square Enix sold Eidos-Montréal, Crystal Dynamics and Square Enix Montréal to Sweden's Embracer Group for about $300 million.","fundingStage":"Subsidiary (Embracer Group)"},
  "ea-motive": {"people":[{"name":"Jade Raymond","title":"Founder & Studio Head","role":"founder"},{"name":"Patrick Klaus","title":"General Manager, Motive Studio","role":"executive"}],"story":"Motive Studio is Electronic Arts' Montréal studio, founded in 2015 by former Ubisoft and Assassin's Creed producer Jade Raymond, who led it until her 2018 departure. The studio co-developed Star Wars Battlefront II, created Star Wars: Squadrons, and delivered the acclaimed Dead Space remake in January 2023. It is also developing an Iron Man game with Marvel.","fundingStage":"Subsidiary (Electronic Arts)","notableClients":["Disney/Lucasfilm","Marvel"]},
  "behaviour-interactive": {"people":[{"name":"Rémi Racine","title":"Founder & Executive Chairman","role":"founder"},{"name":"Stéphanie Marchand","title":"Chief Operating Officer","role":"executive"},{"name":"Nathan Sellyn","title":"Deputy Chief Executive Officer","role":"executive"},{"name":"Stephen Mulrooney","title":"Chief Product Officer & CTO","role":"executive"},{"name":"Roland Ribotti","title":"Chief Financial Officer","role":"executive"},{"name":"Kalina Morin","title":"Senior VP, People & Culture","role":"hiring"}],"story":"Behaviour Interactive traces its roots to 1992, when Rémi Racine founded a Quebec studio that was later renamed Artificial Mind & Movement (A2M) and reverted to Behaviour Interactive in 2010. Now one of Canada's largest independent game studios with 1,300+ staff, its breakout hit is the asymmetric horror game Dead by Daylight (2016), which surpassed 50 million players. Behaviour bought the game's publishing rights from Starbreeze for US$16 million in 2018.","fundingStage":"Private"},
  "gameloft-montreal": {"people":[{"name":"Matthieu Dupont","title":"Head of Studio, Gameloft Montréal","role":"executive","linkedIn":"https://ca.linkedin.com/in/matthieu-dupont-391b7324"}],"story":"Gameloft Montréal is a Canadian studio of the French group Gameloft, established in 2000 and employing nearly 400 people. After two decades focused on mobile games, the studio expanded to PC and console following the major success of Disney Dreamlight Valley (2022). Gameloft was founded in 1999 by Ubisoft co-founder Michel Guillemot and has been owned by Vivendi since 2016.","fundingStage":"Subsidiary (Gameloft / Vivendi)","notableClients":["Disney"]},
  "ludia": {"people":[{"name":"Alexandre Thabet","title":"Founder & CEO","role":"founder"},{"name":"Jimmy Gendron","title":"Chief Executive Officer","role":"executive"}],"story":"Ludia was founded in 2007 in Montréal by Alexandre Thabet and grew into one of Canada's largest independent mobile-game studios, with around 400 employees and titles including Jurassic World Alive, Jurassic World: The Game and Dragons: Rise of Berk. Jam City acquired Ludia for US$165 million in 2021, then sold it back to a group of Québec investors in 2025, with Thabet rejoining as a shareholder and Chairman.","fundingStage":"Private","notableClients":["Universal Pictures","DreamWorks Animation"]},
  "compulsion-games": {"people":[{"name":"Guillaume Provost","title":"Founder & Studio Director","role":"founder"}],"story":"Compulsion Games was founded in 2009 by ex-Arkane Studios developer Guillaume Provost. The Montréal studio made the puzzle-platformer Contrast (2013) and the survival game We Happy Few (2018) before Microsoft acquired it at E3 2018, making it part of Xbox Game Studios. Its most ambitious title, the action-adventure South of Midnight, launched in 2025.","fundingStage":"Subsidiary (Xbox Game Studios / Microsoft)"},
  "red-barrels": {"people":[{"name":"Philippe Morin","title":"Co-founder","role":"founder"},{"name":"David Chateauneuf","title":"Co-founder","role":"founder"},{"name":"Hugo Dallaire","title":"Co-founder","role":"founder"}],"story":"Red Barrels was founded on June 26, 2011 in Montréal by industry veterans Philippe Morin, David Chateauneuf and Hugo Dallaire, whose backgrounds span Prince of Persia, Assassin's Creed, Splinter Cell and Uncharted. The independent studio's debut, the survival-horror game Outlast (2013), and its sequels and co-op spin-off The Outlast Trials have terrified more than 37 million players worldwide.","fundingStage":"Private"},
  "reflector-entertainment": {"people":[{"name":"Alexandre Amancio","title":"Founder & CEO","role":"founder"}],"story":"Reflector Entertainment was founded in 2016 in Montréal by former Ubisoft creative director Alexandre Amancio, backed by Guy Laliberté's Lune Rouge, to build cross-media 'Storyworlds'. Its flagship project, Unknown 9, spans a novel trilogy, podcast, comics and the video game Unknown 9: Awakening. Bandai Namco Entertainment Europe acquired the studio in 2020.","fundingStage":"Subsidiary (Bandai Namco)"},
  "thunder-lotus": {"people":[{"name":"Will Dubé","title":"Founder & CEO","role":"founder"}],"story":"Thunder Lotus Games was founded in 2014 when Will Dubé left his mobile-game job to Kickstart an indie project, rallying friends and former colleagues into a Montréal collective. Their hand-drawn debut Jotun (2015) was crowdfunded, and the studio rose to prominence with the BAFTA-nominated Spiritfarer (2020), a cozy game about death that has sold over 4 million copies. Its 33-player action-roguelike 33 Immortals launched in early access in 2025.","fundingStage":"Private"},
  "kitfox-games": {"people":[{"name":"Tanya X. Short","title":"Co-founder & Captain (CEO)","role":"founder"},{"name":"Jongwoo Kim","title":"Co-founder","role":"founder"},{"name":"Xin Ran Liu","title":"Co-founder","role":"founder"},{"name":"Mike Ditchburn","title":"Co-founder","role":"founder"}],"story":"Kitfox Games was co-founded in June 2013 in Montréal by Tanya X. Short, Jongwoo Kim, Xin Ran Liu and Mike Ditchburn. The indie studio developed Moon Hunters and Boyfriend Dungeon, and has become a notable publisher of deep procedural-simulation games, bringing Dwarf Fortress to Steam in 2022 and publishing Caves of Qud. Short is also the author of works on procedural generation in game design.","fundingStage":"Private"},
  "tribute-games": {"people":[{"name":"Jonathan Lavigne","title":"Co-founder","role":"founder"},{"name":"Jean-François Major","title":"Co-founder","role":"founder"},{"name":"Justin Cyr","title":"Co-founder","role":"founder"}],"story":"Tribute Games was founded on May 9, 2011 in Montréal by former Ubisoft developers Jonathan Lavigne, Jean-François Major and Justin Cyr, who had worked together on a 2007 TMNT handheld game. The studio specializes in retro pixel-art games evoking 1980s arcade titles, including Mercenary Kings, Panzer Paladin and Flinthook. Its breakout hit was the beat-'em-up Teenage Mutant Ninja Turtles: Shredder's Revenge (2022), published by Dotemu.","fundingStage":"Private"},
  "rodeo-fx": {"people":[{"name":"Sébastien Moreau","title":"Founder & CEO","role":"founder"},{"name":"Claude Thibault","title":"Chief Financial Officer","role":"executive"},{"name":"Martin Walker","title":"Chief Technology Officer","role":"executive"},{"name":"Sandra Charlebois","title":"Head of Human Resources","role":"hiring"}],"story":"Rodeo FX was founded in 2006 in Montréal by Sébastien Moreau and began producing feature-film visual effects in 2007. The studio won a 2014 Emmy for its work on Game of Thrones and contributed to the Oscar-winning visual effects of Denis Villeneuve's Dune (2021) and Dune: Part Two (2024). Its credits also include Blade Runner 2049, Stranger Things and numerous major films.","fundingStage":"Private","notableClients":["HBO","Netflix","Warner Bros.","Legendary Pictures"]},
  "dneg-montreal": {"story":"DNEG Montréal is a studio of the global visual-effects and animation company DNEG, which was founded as Double Negative in 1998 in Soho, London, and rebranded as DNEG in 2014. DNEG is one of the industry's most decorated VFX houses, winning Academy Awards for Best Visual Effects on films including Inception, Interstellar, Blade Runner 2049, Tenet, Dune and Dune: Part Two. The Montréal studio is part of its worldwide network spanning London, Vancouver, Mumbai, Los Angeles and more.","fundingStage":"Subsidiary (DNEG)","notableClients":["Warner Bros.","Legendary Pictures","Netflix"]},
  "framestore-montreal": {"story":"Framestore Montréal is a studio of Framestore, the Oscar-, Emmy- and BAFTA-winning visual-effects company founded in London in 1986 by William Sargent and Sharon Reed. Framestore won the Academy Award for Best Visual Effects for Gravity (2014), and its credits include all the Harry Potter films, Guardians of the Galaxy, Paddington and Blade Runner 2049. Its Montréal studio is one of several worldwide, alongside London, New York, Los Angeles, Mumbai and Melbourne.","fundingStage":"Subsidiary (Framestore)","notableClients":["Disney","Warner Bros.","Marvel","Netflix"]},
  "mpc-montreal": {"story":"MPC (Moving Picture Company) was founded in London in 1970 and grew into one of the world's leading visual-effects houses, winning Academy Awards for Life of Pi (2012) and The Jungle Book (2016). Its Montréal studio is one of several global facilities operating under the MPC brand, part of Technicolor Creative Studios. MPC also delivered the photoreal VFX for the 2019 remake of The Lion King.","fundingStage":"Subsidiary (Technicolor / MPC)"},
  "mikros-animation": {"people":[{"name":"Nicolas Delval","title":"Head of Montreal Studio","role":"executive"},{"name":"Julien Meesters","title":"President, Mikros Animation","role":"executive"}],"story":"Mikros Animation traces its roots to a French visual-effects and post-production company founded in 1985, later specializing in CG animated features. Acquired by Technicolor in 2015, it produced films such as Asterix: The Secret of the Magic Potion, PAW Patrol: The Movie and Captain Underpants across studios in Paris and Montréal. In March 2025 it was announced that Montréal's Rodeo FX would acquire Mikros Animation.","fundingStage":"Subsidiary (Technicolor / Rodeo FX)"},
  "cinesite-montreal": {"people":[{"name":"Graham Peddie","title":"General Manager, Cinesite Montréal","role":"executive"}],"story":"Cinesite began in Hollywood in 1991 (with a London office in 1994) and was a subsidiary of Kodak until becoming independent in 2012. In January 2014, with support from Investissement Québec, it opened its Montréal studio and launched a feature-animation division there. Cinesite's VFX credits include No Time to Die, Ant-Man and The Witcher, and its group now spans London, Montréal and Vancouver, including the Image Engine and TRIXTER brands.","fundingStage":"Private"},
  "sony-imageworks-mtl": {"story":"Sony Pictures Imageworks was founded on May 26, 1992 as the visual-effects and animation arm of Sony Pictures, and has won Academy Awards for Spider-Man 2, Into the Spider-Verse and The ChubbChubbs!. Now headquartered in Vancouver, it operates additional studios in Los Angeles and Montréal. Its Montréal facility is one of its newer studios contributing to major live-action VFX and animated features.","fundingStage":"Subsidiary (Sony Pictures)"},
  "keywords-studios-mtl": {"people":[{"name":"Giorgio Guastalla","title":"Co-founder","role":"founder"},{"name":"Teresa Luppino","title":"Co-founder","role":"founder"}],"story":"Keywords Studios was founded in 1998 in Dublin by Giorgio Guastalla and Teresa Luppino, initially providing software localisation before pivoting to the video-games industry. Under CEO Andrew Day (from 2009) it IPO'd on the London Stock Exchange in 2013 and grew through dozens of acquisitions into the world's largest technical and creative services provider to the games industry. Its Montréal operation is one of its largest, handling QA, art, localisation and player support; the company was taken private by EQT in 2024.","fundingStage":"Acquired"},
  "bausch-health": {"people":[{"name":"Thomas J. Appio","title":"Chief Executive Officer","role":"executive"},{"name":"Jean-Jacques Charhon","title":"Executive Vice President, Chief Financial Officer","role":"executive"},{"name":"Mirza Dautbegovic","title":"Executive Vice President, Chief Operating Officer","role":"executive"},{"name":"Kathleen Fitzpatrick","title":"Executive Vice President, Chief Human Resources and Communications Officer","role":"executive"},{"name":"Jonathan Sadeh","title":"Executive Vice President, Chief Medical Officer and Head of R&D","role":"executive"},{"name":"Cees Heiman","title":"Senior Vice President, Europe and Canada","role":"executive"}],"story":"Bausch Health traces its origins to ICN Pharmaceuticals, founded in 1959/1960 by Milan Panić, which renamed itself Valeant Pharmaceuticals International in 2003. After the 2010 Valeant–Biovail merger the company established its global headquarters in Laval, Quebec, and following a period of aggressive acquisitions (including Medicis and Bausch & Lomb) it rebranded as Bausch Health Companies in 2018. Its eye-health unit Bausch + Lomb was later carved out via IPO.","fundingStage":"Public"},
  "pfizer-canada": {"people":[{"name":"An Van Gerven","title":"President, Pfizer Canada","role":"executive"}],"story":"Pfizer opened its first Canadian operations in Montréal in 1953 and moved to its Kirkland, Quebec campus in 1975, which today houses the Canadian head office and manufacturing for its pharmaceuticals and animal-health businesses. In 2011 Pfizer invested roughly $22 million to modernize and consolidate its Kirkland head-office facilities. Pfizer Canada led the country's COVID-19 vaccine rollout with partner BioNTech.","fundingStage":"Subsidiary (Pfizer Inc.)"},
  "novartis-canada": {"people":[{"name":"Dimitri Gitas","title":"Country President, Novartis Canada","role":"executive"}],"story":"Novartis Pharmaceuticals Canada is the Canadian arm of the Swiss pharmaceutical giant Novartis, which itself was formed in 1996 from the merger of Ciba-Geigy and Sandoz. In May 2023 Novartis Canada relocated its head office from Dorval to Place Gare Viger in the historic district of Old Montréal, positioning itself within the city's health-innovation ecosystem. Its focus areas include oncology, immunology and neuroscience.","fundingStage":"Subsidiary (Novartis AG)"},
  "merck-canada": {"people":[{"name":"David D. Jones","title":"President and Managing Director, Merck Canada","role":"executive"},{"name":"Marie-Claude Lapointe","title":"Executive Director, Human Resources","role":"hiring"}],"story":"Merck's Canadian presence grew out of Charles E. Frosst & Co., a Montréal pharmaceutical firm founded in 1899 that Merck acquired in 1965 to form Merck-Frosst Canada. Its Kirkland, Quebec campus, established as the Merck Frosst Centre for Therapeutic Research in 1969, became one of Canada's largest biomedical research facilities. Known as MSD outside the US and Canada, the company markets the world's best-selling drug, the cancer immunotherapy Keytruda.","fundingStage":"Subsidiary (Merck & Co.)"},
  "abbvie-canada": {"people":[{"name":"Tanu Misra","title":"Vice President and General Manager, AbbVie Canada","role":"executive"}],"story":"AbbVie was created on January 1, 2013 when Abbott Laboratories spun off its branded biopharmaceutical business into a standalone company anchored by the anti-inflammatory blockbuster Humira. AbbVie Canada operates as the company's Canadian affiliate from Saint-Laurent (Montréal), focused on immunology and oncology, with products including Humira and Skyrizi. Humira was the world's best-selling drug for years before being overtaken by Keytruda.","fundingStage":"Subsidiary (AbbVie Inc.)"},
  "gsk-canada": {"people":[{"name":"Sridhar Venkatesh","title":"President & General Manager, GSK Canada","role":"executive"},{"name":"Jacky Tovell","title":"HR Country Head, GSK Canada","role":"hiring"}],"story":"GSK Canada is the Canadian operation of the UK pharmaceutical major GlaxoSmithKline, which rebranded as GSK in 2022. Its Laval, Quebec laboratory was upgraded with a roughly $50 million investment to become the company's North American research and administrative headquarters for its vaccines division. GSK also runs a vaccine manufacturing facility in Sainte-Foy, Quebec, and its Canadian focus spans vaccines, respiratory medicines and HIV treatments.","fundingStage":"Subsidiary (GSK plc)"},
  "knight-therapeutics": {"people":[{"name":"Jonathan Ross Goodman","title":"Founder & former CEO","role":"founder"},{"name":"Samira Sakhia","title":"President and Chief Executive Officer","role":"executive"},{"name":"Arvind Utchanah","title":"Chief Financial Officer","role":"executive"},{"name":"Amal Khoury","title":"Chief Business Officer","role":"executive"}],"story":"Knight Therapeutics was founded in February 2014 by Jonathan Ross Goodman, co-founder of Paladin Labs, shortly after Paladin was acquired by Endo for about $3.2 billion. The Montréal-based, TSX-listed specialty pharma acquires, in-licenses and markets prescription drugs, consumer-health products and medical devices in Canada and select international markets. It expanded into Latin America through its acquisition of Grupo Biotoscana.","fundingStage":"Public"},
  "cellcarta": {"people":[{"name":"Dusty Tenney","title":"Chief Executive Officer","role":"executive"},{"name":"Elliot Miller","title":"Chief Financial Officer","role":"executive"},{"name":"Nancy El Sayegh","title":"Chief People & Legal Officer, General Counsel","role":"executive"},{"name":"Louis Norton","title":"Chief Information Officer","role":"executive"}],"story":"CellCarta was formed in 2019 from the combination of Montréal-based contract research organization Caprion Biosciences (immunology and proteomics) and Antwerp-based HistoGeneX (histopathology and genomics), rebranding under the CellCarta name in early 2021. Backed by Arsenal Capital Partners, the precision-medicine CRO provides biomarker and immune-monitoring services to biopharma, expanding through acquisitions such as Mosaic Laboratories, Reveal Biosciences and Clinical Logistics.","fundingStage":"Private"},
  "ability-biotherapeutics": {"people":[{"name":"Carles Domènech","title":"Co-founder & CEO","role":"founder","linkedIn":"https://www.linkedin.com/in/carlesdomenech/"},{"name":"Jordi Espadaler","title":"Co-founder","role":"founder"},{"name":"Héctor Pérez-Montoyo","title":"Chief Operating Officer and Head of R&D","role":"executive"},{"name":"David Saxner","title":"Chief Business Officer","role":"executive"},{"name":"Petr Vinduška","title":"Chief Financial Officer","role":"executive"}],"story":"Ability Pharmaceuticals was founded in late 2009 (initially as AB-Therapeutics) by Dr. Carles Domènech and Dr. Jordi Espadaler, spun out of the biotech AB-Biotics, and is headquartered near Barcelona, Spain. The clinical-stage company develops novel anticancer therapies targeting lipid metabolism, led by its first-in-class oral compound ABTL0812, which induces cancer-cell death by autophagy. Its lead program has advanced into Phase 2b trials in pancreatic cancer, supported by EU Horizon Europe funding.","fundingStage":"Private"},
  "altasciences": {"people":[{"name":"Marie-Hélène Raigneau","title":"Chief Executive Officer","role":"executive"},{"name":"Chris Perkin","title":"Executive Chairman","role":"executive"},{"name":"Mariano Rodriguez","title":"Executive Vice President and Chief Financial Officer","role":"executive"},{"name":"Dr. Beatrice Setnik","title":"Chief Scientific Officer","role":"executive"},{"name":"Catherine Konidas","title":"Chief Administrative Officer","role":"executive"}],"story":"Altasciences traces its roots to 1992 and the Montreal-based clinical-research firm Algorithme Pharma, which was consolidated with other businesses under the Altasciences brand in 2013 to form an integrated mid-size CRO/CDMO spanning preclinical, clinical pharmacology and manufacturing. It grew in part through acquisitions and was acquired by life-sciences investor Novo Holdings in February 2021.","fundingStage":"Subsidiary (Novo Holdings)"},
  "charles-river-labs-mtl": {"people":[{"name":"Henry L. Foster","title":"Founder","role":"founder"}],"story":"Charles River Laboratories was founded in 1947 by veterinarian Dr. Henry L. Foster, who started a one-man lab in Boston overlooking the Charles River. Now a NYSE-listed global leader in preclinical and safety-assessment services (IPO 1999), the company operates a major Montreal-area campus in Senneville, one of the largest sites in its worldwide network.","fundingStage":"Public"},
  "ircm": {"people":[{"name":"Jacques Genest","title":"Founder","role":"founder"},{"name":"Jean-François Côté","title":"President and Scientific Director","role":"executive"},{"name":"Michel Cayouette","title":"Vice-President, Research and Academic Affairs","role":"executive"},{"name":"Nadia Dubé","title":"Vice-President, Development and Administration","role":"executive"},{"name":"Rémi Rabasa-Lhoret","title":"Vice-President, Clinic and Clinical Research","role":"executive"},{"name":"Isabelle Audet","title":"Director of Human Resources","role":"hiring"}],"story":"The Institut de recherches cliniques de Montréal was founded in 1967 by Dr. Jacques Genest, a pioneering Quebec researcher in hypertension, with a $3M grant from the Government of Quebec. Genest, who directed the institute until 1984, built it into an early model of applying molecular biology to clinical medicine; it remains an independent biomedical research institute affiliated with the Université de Montréal and McGill.","fundingStage":"Non-profit"},
  "the-neuro-mcgill": {"people":[{"name":"Wilder Penfield","title":"Founder & First Director","role":"founder"},{"name":"Edward Fon","title":"Director, The Neuro (Montreal Neurological Institute-Hospital)","role":"executive"},{"name":"Marisa Albanese","title":"Director, Administration and Operations","role":"executive"},{"name":"Annabel Seyller","title":"Chief Operating Officer, Open Science","role":"executive"}],"story":"The Montreal Neurological Institute (The Neuro) was established in 1934 by neurosurgery pioneer Wilder Penfield, funded largely by a Rockefeller Foundation grant with support from Quebec, the City of Montreal and private donors. Penfield served as its first director until 1960, developing pioneering surgical treatments for epilepsy; the McGill institute and hospital later became the first in the world to adopt an institutional open-science policy.","fundingStage":"University lab"},
  "admare-bioinnovations": {"people":[{"name":"Gordon C. McCauley","title":"Founding President & CEO","role":"founder"},{"name":"Matthew J. Carlyle","title":"President, CEO and Director","role":"executive"},{"name":"Frédéric Lemaître Auger","title":"Executive Vice President, Investments","role":"executive"},{"name":"Joseph Mancini","title":"Vice President, Research","role":"executive"},{"name":"Sarah Gallagher","title":"Vice President, People and Culture","role":"hiring"}],"story":"adMare BioInnovations was created in May 2019 through the merger of the Centre for Drug Research and Development (CDRD) and the NEOMED Institute, forming a pan-Canadian not-for-profit that builds, finances and mentors life-sciences companies. Gordon C. McCauley — previously president and CEO of CDRD — served as its founding president and CEO; the organization runs a Montreal campus in the Technoparc in Saint-Laurent.","fundingStage":"Non-profit"},
  "montreal-invivo": {"people":[{"name":"Stéphanie Doyle","title":"President and Chief Executive Officer","role":"executive"},{"name":"Claudie Noël","title":"Senior Director, Operations","role":"executive"}],"story":"Montréal InVivo is the non-profit organization designated as the life sciences and health-technologies (LSHT) cluster of Greater Montréal. It connects hundreds of member organizations — spanning pharma, biotech, medtech, digital health, research centres and CROs — to strengthen the sector's growth, competitiveness and visibility.","fundingStage":"Non-profit"},
  "national-bank": {"people":[{"name":"Laurent Ferreira","title":"President and Chief Executive Officer","role":"executive"},{"name":"Marie-Chantal Gingras","title":"Chief Financial Officer and Executive Vice-President, Finance","role":"executive"},{"name":"Julie Lévesque","title":"Executive Vice-President, Personal Banking","role":"executive"},{"name":"Nancy Paquet","title":"Executive Vice-President, Wealth Management","role":"executive"},{"name":"Étienne Dubuc","title":"Executive Vice-President, Capital Markets","role":"executive"},{"name":"Dominic Paradis","title":"Executive Vice-President and General Counsel, Enterprise Technology and Resilience","role":"executive"}],"story":"National Bank of Canada traces its origins to Banque Nationale, founded in 1859 in Quebec City by francophone businessmen seeking a bank under local French-Canadian control. The modern National Bank of Canada was formed in 1979 through the merger of Banque Canadienne Nationale and the Provincial Bank of Canada; it is Canada's sixth-largest chartered bank and the largest headquartered in Quebec.","fundingStage":"Public"},
  "desjardins": {"people":[{"name":"Alphonse Desjardins","title":"Founder","role":"founder"},{"name":"Dorimène Desjardins","title":"Co-founder","role":"founder"},{"name":"Denis Dubois","title":"President and Chief Executive Officer","role":"executive"}],"story":"Desjardins Group grew out of the Caisse populaire de Lévis, founded on December 6, 1900 by journalist Alphonse Desjardins and his wife and collaborator Dorimène Desjardins — the first savings and credit cooperative in North America. It has since become the largest federation of credit unions (caisses populaires) in North America and Quebec's leading financial cooperative.","fundingStage":"Cooperative"},
  "bmo": {"story":"The Bank of Montreal was founded in 1817 when nine Montreal merchants signed the Articles of Association, creating the Montreal Bank — Canada's oldest incorporated bank. It effectively served as Canada's central bank until the Bank of Canada was created in 1935; its legal head office remains the neoclassical building on Place d'Armes in Old Montreal, though the operational head office moved to Toronto in 1977.","fundingStage":"Public"},
  "td-bank": {"story":"TD Bank Group was formed on February 1, 1955 through the merger of the Bank of Toronto (founded 1855) and the Dominion Bank (founded 1869), creating The Toronto-Dominion Bank. One of Canada's Big Five and a top-10 North American bank by assets, it has operated in Quebec for over 150 years, with its Montreal main branch in the landmark TD Building at 500 Saint-Jacques.","fundingStage":"Public"},
  "rbc": {"story":"The Royal Bank of Canada was founded in 1864 in Halifax as the Merchants' Bank of Halifax by a group of eight local merchants (including Thomas Kinnear, Edward Kenny and William Cunard). It received a federal charter in 1869 and adopted the Royal Bank of Canada name in 1901; today Canada's largest bank, its head office is 1 Place Ville Marie, built in 1962 as its headquarters.","fundingStage":"Public"},
  "scotiabank": {"story":"The Bank of Nova Scotia (Scotiabank) was founded in 1832 in Halifax by a group of local businessmen, with the Honourable William Lawson elected as its first president; it opened for business on August 10, 1832. Its general offices moved to Toronto by 1900, and it is now one of Canada's Big Five and the country's most internationally focused bank, with its Montreal presence anchored in Scotia Tower on Sherbrooke Ouest.","fundingStage":"Public"},
  "cibc": {"story":"CIBC was created on June 1, 1961 through the merger of the Canadian Bank of Commerce (founded 1867 by William McMaster) and the Imperial Bank of Canada (founded 1875 by Henry Stark Howland) — the largest merger of chartered banks in Canadian history at the time. One of Canada's Big Five, its Montreal main banking centre sits in the 45-storey CIBC Tower on René-Lévesque, completed in 1962.","fundingStage":"Public"},
  "morgan-stanley": {"story":"Morgan Stanley was founded in 1935 in New York by Henry S. Morgan and Harold Stanley after the Glass-Steagall Act forced J.P. Morgan & Co. to split off its investment-banking business. The global investment bank opened its Montreal technology office in the Cité du Multimédia in 2008 with about 160 people; it has since grown into one of the firm's largest technology hubs (1,500+ technologists) and a recognized Montreal Top Employer.","fundingStage":"Public"},
  "intact-financial": {"people":[{"name":"Charles Brindamour","title":"Chief Executive Officer","role":"executive"}],"story":"Intact Financial traces its roots to insurers dating back to the 19th century but took its current form in 2009, when ING Groep sold its entire stake in ING Canada and the company was renamed Intact Financial Corporation. Led by CEO Charles Brindamour, it became an independent, widely held Canadian company and is now the country's largest provider of property and casualty insurance, trading on the TSX under IFC.","fundingStage":"Public"},
  "ia-financial": {"people":[{"name":"Denis Ricard","title":"President and Chief Executive Officer","role":"executive"},{"name":"Éric Jobin","title":"Executive Vice-President, CFO and Chief Actuary","role":"executive"},{"name":"Stephan Bourbonnais","title":"Executive Vice-President, Wealth Management","role":"executive"},{"name":"Marie-Annick Bonneau","title":"Executive Vice-President and Chief Risk Officer","role":"executive"}],"story":"iA Financial Group's origins go back to Alliance Nationale, a francophone mutual life insurer founded in 1892, and Industrial Life Insurance Company, founded in Quebec City in 1905. The two merged in 1987 to form Industrial Alliance, now iA Financial Group, one of Canada's oldest and largest insurance and wealth-management organizations. Headquartered in Quebec City, it is publicly traded and serves millions of clients across Canada and the United States.","fundingStage":"Public"},
  "sun-life": {"people":[{"name":"Matthew Hamilton Gault","title":"Founder","role":"founder"},{"name":"Robert Dumas","title":"President and Chief Executive Officer, Sun Life Quebec","role":"executive"},{"name":"Jessica Tan","title":"President, Sun Life Canada","role":"executive"}],"story":"Sun Life was founded in Montreal in 1865 as the Sun Insurance Company of Montreal by Matthew Hamilton Gault, an Irish immigrant and later Member of Parliament for Montreal West. Operations began in 1871, and by the end of the 19th century the company had expanded across the Americas, Europe and Asia. Now Sun Life Financial, it is a leading international insurer and financial-services company; its landmark Sun Life Building on Dorchester Square, completed in 1931, was once the largest building in the British Empire by floor area.","fundingStage":"Public"},
  "manulife": {"people":[{"name":"Patrick Graham","title":"President and Chief Executive Officer, Manulife Canada","role":"executive"}],"story":"Manulife was incorporated in 1887 as The Manufacturers Life Insurance Company by an Act of Parliament, with Canada's first prime minister, Sir John A. Macdonald, serving as its first president. It grew into one of the world's largest life insurers, operating in Canada, the United States (as John Hancock) and across Asia. Its Quebec head office is the Class-AAA Maison Manuvie tower in downtown Montreal, opened in 2017.","fundingStage":"Public"},
  "beneva": {"people":[{"name":"Jean-François Chalifoux","title":"President and Chief Executive Officer","role":"executive"},{"name":"Christian Fournier","title":"Executive Vice-President and Leader, Property and Casualty Insurance","role":"executive"},{"name":"Mélissa Gilbert","title":"Executive Vice-President and Leader, Finance","role":"executive"},{"name":"Stéphane Morency","title":"Executive Vice-President and Leader, Strategy, Customer Experience and Marketing","role":"executive"},{"name":"Pierre Marc Bellavance","title":"Executive Vice-President and Leader, Legal and Corporate Services","role":"executive"}],"story":"Beneva was created in 2020 from the merger of two Quebec insurers, La Capitale (founded 1940) and SSQ Insurance (founded 1944), a deal announced in January 2020 and completed that July. The combined mutual adopted the Beneva brand in December 2020, becoming the largest insurance mutual in Canada with over 3.5 million members and clients. Its head office is in Quebec City, with service offices across Montreal.","fundingStage":"Non-profit"},
  "cdpq": {"people":[{"name":"Charles Emond","title":"President and Chief Executive Officer","role":"executive"},{"name":"Sarah-Émilie Bouchard","title":"Executive Vice-President, Global Strategy and Chief Operating Officer","role":"executive"},{"name":"Emmanuelle Leclerc-Granger","title":"Executive Vice-President and Chief Financial and Information Officer","role":"executive"},{"name":"Kim Thomassin","title":"Executive Vice-President and Head of Québec","role":"executive"},{"name":"Ève Giard","title":"Executive Vice-President, Talent and Performance","role":"hiring"}],"story":"The Caisse de depot et placement du Quebec was established on July 15, 1965 by an act of Quebec's National Assembly under the government of Jean Lesage, as part of the Quiet Revolution, to manage funds of the newly created Quebec Pension Plan. Now branded La Caisse, it is a global institutional investor managing public and parapublic pension and insurance plans, and is the second-largest pension fund in Canada, with roughly C$473 billion in assets at the end of 2024.","fundingStage":"Crown corporation"},
  "psp-investments": {"people":[{"name":"Deborah K. Orida","title":"President and Chief Executive Officer","role":"executive"},{"name":"Patrick Charbonneau","title":"Chief Investment Officer","role":"executive"}],"story":"The Public Sector Pension Investment Board (PSP Investments) is a Crown corporation established by Parliament through the Public Sector Pension Investment Board Act in September 1999. It manages the pension assets of the federal Public Service, the Canadian Forces, the RCMP and the Reserve Force, with net assets under management of about C$264.9 billion in fiscal 2024. Its registered head office is in Ottawa, but its principal business office and most staff are in downtown Montreal.","fundingStage":"Crown corporation"},
  "fiera-capital": {"people":[{"name":"Jean-Guy Desjardins","title":"Founder, Chair & CEO","role":"founder"},{"name":"Maxime Ménard","title":"Global President and Chief Executive Officer","role":"executive"},{"name":"Gabriel Castiglio","title":"Executive Director, Global Chief Operating Officer","role":"executive"},{"name":"Lucas Pontillo","title":"Executive Director, Global Chief Financial Officer and Head of Corporate Strategy","role":"executive"}],"story":"Fiera Capital was founded in 2003 by veteran investor Jean-Guy Desjardins, who had earlier co-founded TAL Global Asset Management in 1972. He built Fiera into a leading independent, publicly traded asset-management firm through a series of acquisitions, and returned as Global CEO in 2023. Its global headquarters occupy the north tower of 1981 McGill College, renamed the Fiera Capital Tower in 2019.","fundingStage":"Public"},
  "national-bank-investments": {"people":[{"name":"Éric-Olivier Savoie","title":"President and Chief Executive Officer","role":"executive"},{"name":"Martin Lefebvre","title":"Chief Investment Officer and Strategist","role":"executive"}],"story":"National Bank Investments (NBI) was established in 2003 as the asset-management arm of National Bank of Canada, one of the country's largest banks. It offers mutual funds, ETFs and managed solutions and is a leading retail open-architecture provider in Canada, with assets under management exceeding C$80 billion. It operates from the bank's downtown Montreal head office.","fundingStage":"Subsidiary (National Bank of Canada)"},
  "addenda-capital": {"people":[{"name":"Carmand Normand","title":"Founder","role":"founder"},{"name":"Roger J. Beauchemin","title":"President and Chief Executive Officer","role":"executive"},{"name":"Ian A. McKinnon","title":"Chief Investment Officer","role":"executive"},{"name":"Charles Leblanc","title":"Chief Operating Officer","role":"executive"},{"name":"Isabelle Gosselin","title":"Executive Vice-President, Talent Management","role":"hiring"}],"story":"Addenda Capital was founded in 1996 by Carmand Normand as a Montreal-based institutional investment-management firm, building its early reputation on Canadian bond and fixed-income management. In April 2008 The Co-operators acquired Addenda in a deal valuing its equity at about C$306.5 million, and it has operated as a subsidiary since. The firm manages assets for pension, insurance, corporate, foundation and private-wealth clients.","fundingStage":"Subsidiary (Co-operators)"},
  "fidelity-canada": {"story":"Fidelity Investments Canada, the Canadian asset-management arm of US-based Fidelity Investments, opened its doors on October 19, 1987 (the day of the Black Monday crash). Headquartered in Toronto, it is one of Canada's largest asset managers, with well over C$240 billion in assets under management. It runs regional offices in Montreal, Calgary and Vancouver serving advisors and investors.","fundingStage":"Subsidiary (Fidelity Investments)"},
  "cgi": {"people":[{"name":"Serge Godin","title":"Co-founder & Founder Chairman","role":"founder"},{"name":"Andre Imbeau","title":"Co-founder","role":"founder"},{"name":"Timothy J. Hurlebaus","title":"President and Chief Executive Officer","role":"executive"}],"story":"CGI was founded in June 1976 in Quebec City by Serge Godin, joined by co-founder Andre Imbeau, initially run from Godin's basement with a single phone; the name stands for Conseillers en gestion et informatique. The company went public in 1986 on the Toronto Stock Exchange and grew through acquisitions into one of the world's largest independent IT and business-consulting firms. Its global headquarters are in downtown Montreal.","fundingStage":"Public"},
  "accenture": {"story":"Accenture originated as the business and technology consulting arm of accounting firm Arthur Andersen, formally organized as Andersen Consulting in 1989. After splitting from Arthur Andersen, it adopted the name Accenture on January 1, 2001 and went public on the NYSE later that year. It is now a global professional-services company specializing in technology, strategy and digital consulting; its Montreal office occupies a renovated floor of the landmark Place Ville Marie tower.","fundingStage":"Public"},
  "deloitte": {"story":"Deloitte traces its origins to 1845, when William Welch Deloitte opened an accounting office in London. Through a series of mergers over the following century and a half it became Deloitte Touche Tohmatsu, one of the Big Four professional-services firms offering audit, consulting, tax and advisory services worldwide. In Montreal the firm anchors the Deloitte Tower, the city's first LEED Platinum office tower, next to the Bell Centre.","fundingStage":"Private"},
  "kpmg": {"people":[{"name":"Stéphan Drolet","title":"Managing Partner, Quebec — KPMG in Canada","role":"executive"}],"story":"KPMG is one of the Big Four global professional-services networks, formed in 1987 through the merger of Peat Marwick International and Klynveld Main Goerdeler; the name combines the initials of Piet Klynveld, William Barclay Peat, James Marwick and Reinhard Goerdeler. Its Canadian arm, KPMG LLP, provides audit, tax and advisory services, with the Montreal office occupying the 34-storey KPMG Tour downtown.","fundingStage":"Private"},
  "pwc": {"people":[{"name":"Nochane Rousseau","title":"Vice-Chair & Managing Partner, Quebec and Eastern Canada — PwC Canada","role":"executive"}],"story":"PwC (PricewaterhouseCoopers) is one of the Big Four professional-services firms, created in 1998 by the merger of Price Waterhouse and Coopers & Lybrand — lineages tracing to 19th-century London accountants Samuel Lowell Price and William Cooper. The Canadian firm offers assurance, tax and consulting services, with its Montreal practice high in the 1250 René-Lévesque tower.","fundingStage":"Private"},
  "ey": {"people":[{"name":"François Tellier","title":"Managing Partner, Eastern Canada & Office Managing Partner, Montréal — EY Canada","role":"executive"}],"story":"EY (Ernst & Young) is one of the Big Four professional-services organizations, formed in 1989 by the merger of Ernst & Whinney and Arthur Young & Co., firms rooted in the practices of A.C. Ernst and Arthur Young. EY Canada delivers assurance, tax, consulting and strategy-and-transactions services, with a Montreal practice in the downtown de Maisonneuve district.","fundingStage":"Private"},
  "bell-canada": {"people":[{"name":"Mirko Bibic","title":"President & CEO, BCE Inc. and Bell Canada","role":"executive","linkedIn":"https://ca.linkedin.com/in/mirkobibic/"},{"name":"Karine Moses","title":"Vice-Chair, Québec & Senior Vice-President, Sales — Bell","role":"executive"},{"name":"Nikki Moffat","title":"EVP, Corporate Services & Chief Human Resources Officer — Bell","role":"hiring"}],"story":"Bell Canada was incorporated in 1880 by a special Act of Parliament as The Bell Telephone Company of Canada, taking its name from telephone inventor Alexander Graham Bell, whose family had settled near Brantford, Ontario. Today it is the principal telecommunications subsidiary of publicly traded parent BCE Inc., offering wireless, internet, TV and media services, with head office at the Bell Campus on Nuns' Island in Verdun.","fundingStage":"Subsidiary (BCE Inc.)"},
  "telus": {"people":[{"name":"François Gratton","title":"Executive Vice-President, TELUS & Group President; leads TELUS Québec (Montréal-based)","role":"executive"}],"story":"TELUS is one of Canada's largest telecommunications companies, formed in 1990 out of the provincial Crown corporation Alberta Government Telephones and later merged with BC Tel in 1999. Publicly traded and headquartered in Vancouver, it offers wireless, internet, TV and health and digital services; its Montreal office occupies Place TELUS downtown near Square-Victoria.","fundingStage":"Public"},
  "videotron": {"people":[{"name":"André Chagnon","title":"Founder","role":"founder"},{"name":"Pierre Karl Péladeau","title":"President & CEO — Vidéotron (and Quebecor)","role":"executive"},{"name":"Jean-François Lescadres","title":"Senior Vice-President & Chief Financial Officer — Vidéotron","role":"executive"}],"story":"Vidéotron was founded in 1964 by electrician André Chagnon as Télécâble Vidéotron, launching northern Montreal's first cable-TV network with just 66 subscribers. It grew through acquisitions into Quebec's leading cable, internet and TV provider before being acquired by Pierre Karl Péladeau's Quebecor in 2000, and expanded nationally after buying Freedom Mobile in 2023.","fundingStage":"Subsidiary (Quebecor)"},
  "quebecor": {"people":[{"name":"Pierre Péladeau","title":"Founder","role":"founder"},{"name":"Pierre Karl Péladeau","title":"President & CEO — Quebecor Inc.","role":"executive"},{"name":"Hugues Simard","title":"Chief Financial Officer — Quebecor Inc.","role":"executive"}],"story":"Quebecor traces to 1950, when Pierre Péladeau bought his first newspaper, Le Journal de Rosemont, with a $1,500 loan from his mother; he launched Le Journal de Montréal in 1964 and incorporated Quebecor Inc. in 1965. The Montreal-based media and telecom conglomerate grew into one of the world's largest commercial printers and now owns Vidéotron and TVA Group; it trades publicly on the Toronto Stock Exchange.","fundingStage":"Public"},
  "sap": {"people":[{"name":"Cindy Fagen","title":"Managing Director, SAP Labs Canada (oversees Montréal, Waterloo, Vancouver)","role":"executive"}],"story":"SAP was founded in 1972 in Weinheim, Germany by five former IBM engineers — Dietmar Hopp, Hasso Plattner, Claus Wellenreuther, Klaus Tschira and Hans-Werner Hector — and became the world's leading enterprise-software maker, best known for its ERP suite. SAP Labs Montreal is an R&D office in the Place Ville Marie tower that added an engineering unit working on SAP's Consumer Industry Cloud.","fundingStage":"Subsidiary (SAP SE)"},
  "autodesk": {"people":[{"name":"Diana Colella","title":"Executive Vice President, Media & Entertainment (Montréal-based)","role":"executive"}],"story":"Autodesk, the design-software company behind AutoCAD, was founded in 1982 by a group led by John Walker. Its Montreal presence and Media & Entertainment division grew largely from acquisitions of local firms — notably Discreet Logic, founded in Montreal in 1991 by Richard Szalwinski and acquired in 1998, along with technology from Softimage — and its high-end film and VFX tools like Flame remained headquartered in Montreal.","fundingStage":"Subsidiary (Autodesk, Inc.)"},
  "oracle": {"story":"Oracle was founded in 1977 by Larry Ellison, Bob Miner and Ed Oates, pioneering the commercial relational database and growing into a giant in enterprise software and cloud infrastructure. Its Montreal office serves Quebec enterprise and cloud customers from a downtown location near McGill metro.","fundingStage":"Subsidiary (Oracle Corporation)"},
  "cisco": {"people":[{"name":"Raj Juneja","title":"President, Cisco Canada","role":"executive"}],"story":"Cisco Systems was founded in 1984 by Stanford computer scientists Leonard Bosack and Sandy Lerner, and became the dominant maker of networking hardware, security and collaboration software. Its Montreal office is a downtown sales and engineering presence on McGill College Avenue.","fundingStage":"Subsidiary (Cisco Systems, Inc.)"},
  "ibm": {"people":[{"name":"Deb Pimentel","title":"President & General Manager, Technology — IBM Canada","role":"executive","linkedIn":"https://ca.linkedin.com/in/deb-pimentel-970581b"}],"story":"IBM traces its roots to 1911 and the Computing-Tabulating-Recording Company, renamed International Business Machines in 1924, and is one of the world's oldest and largest technology and consulting companies. IBM Canada has a long history in Montreal; its downtown office focuses on enterprise computing, cloud, consulting and AI (watsonx), separate from the company's semiconductor-packaging plant in Bromont.","fundingStage":"Subsidiary (IBM Corporation)"},
  "unity": {"story":"Unity Technologies was founded in 2004 in Copenhagen (originally as Over the Edge Entertainment) by David Helgason, Nicholas Francis and Joachim Ante, and its real-time 3D engine became the world's most widely used game-development platform. Now publicly traded (NYSE: U), Unity runs a large R&D hub in Montreal's Le Nordelec building in Saint-Henri, working on the core engine and creative tools.","fundingStage":"Public"},
  "workday": {"people":[{"name":"Edward Charter","title":"Country Leader, Canada — Workday","role":"executive"}],"story":"Workday was founded in 2005 by Dave Duffield and Aneel Bhusri, veterans of PeopleSoft, to build a cloud-native suite for enterprise HR (HCM) and financial management. Now publicly traded on NASDAQ, the company runs a Montreal office in the landmark Place Ville Marie tower.","fundingStage":"Public"},
};
